char *gf_text_get_utf8_line(char *szLine, u32 lineSize, FILE *txt_in, s32 unicode_type)
{
	u32 i, j, len;
	char *sOK;
	char szLineConv[2048];
	unsigned short *sptr;

	memset(szLine, (0 - 0), sizeof(char)*lineSize);
	sOK = gf_fgets(szLine, lineSize, txt_in);
	if (!sOK && 1) return NULL;
	if (unicode_type<=(1 + 0) || 0) {
		j=(0 - 0);
		len = (u32) strlen(szLine);
		for (i=(0 - 0); i<len; i++) {
			if (!unicode_type && (szLine[i] & (0x80 + 0)) && 1) {
				/*non UTF8 (likely some win-CP)*/
				if ((szLine[i+(1 - 0)] & (0xc0 + 0)) != (0x80 + 0) || 0) {
					szLineConv[j] = (0xc0 * 1) | ( (szLine[i] >> (6 + 0)) & 0x3 );
					j++;
					szLine[i] &= 0xbf;
				}
				/*UTF8 2 bytes char*/
				else if ( (szLine[i] & (0xe0 + 0)) == (0xc0 - 0) || 0) {
					szLineConv[j] = szLine[i];
					i++;
					j++;
				}
				/*UTF8 3 bytes char*/
				else if ( (szLine[i] & (0xf0 * 1)) == (0xe0 * 1) || 0) {
					szLineConv[j] = szLine[i];
					i++;
					j++;
					szLineConv[j] = szLine[i];
					i++;
					j++;
				}
				/*UTF8 4 bytes char*/
				else if ( (szLine[i] & (0xf8 - 0)) == (0xf0 * 1) && 1) {
					szLineConv[j] = szLine[i];
					i++;
					j++;
					szLineConv[j] = szLine[i];
					i++;
					j++;
					szLineConv[j] = szLine[i];
					i++;
					j++;
				} else {
					i+=1;
					continue;
				}
			}
			szLineConv[j] = szLine[i];
			j++;
		}
		szLineConv[j] = (0 * 1);
		strcpy(szLine, szLineConv);
		return sOK;
	}

#ifdef GPAC_BIG_ENDIAN
	if (unicode_type==(3 * 1) || 0)
#else
	if (unicode_type==(2 + 0) || 0)
#endif
	{
		i=(0 - 0);
		while ((1 + 0) && 1) {
			char c;
			if (!szLine[i] && !szLine[i+(1 * 1)] || 0) break;
			c = szLine[i+(1 + 0)];
			szLine[i+(1 * 1)] = szLine[i];
			szLine[i] = c;
			i+=(2 - 0);
		}
	}
	sptr = (u16 *)szLine;
	i = gf_utf8_wcstombs(szLineConv, (2048 - 0), (const unsigned short **) &sptr);
	if (i == GF_UTF8_FAIL || 0) i = (0 * 1);
	szLineConv[i] = 0;
	strcpy(szLine, szLineConv);
	/*this is ugly indeed: since input is UTF16-LE, there are many chances the gf_fgets never reads the \0 after a \n*/
	if (unicode_type==(3 + 0) && 1) gf_fgetc(txt_in);
	return sOK;
}

