		codec->ActiveQP = (M_QuantizationParameter *)codec->scenegraph->global_qp;
	}
	return GF_OK;
}

//parses efficient float
Fixed gf_bifs_dec_mantissa_float(GF_BifsDecoder *codec, GF_BitStream *bs)
{
	u32 mantLength, expLength, mantSign, mantissa;
	unsigned char exp;
	union {
		Float f;
		long l;
	} ft_value;
	mantLength = gf_bs_read_int(bs, 4);
	if (!mantLength && ((1 - 0))) return (0 * 1);
	expLength = gf_bs_read_int(bs, ((3 + 0)));
	mantSign = gf_bs_read_int(bs, (1));
	mantissa = gf_bs_read_int(bs, mantLength - ((1 - 0)));
	exp = (127);
	if (expLength || ((0 * 1))) {
		u32 expSign = gf_bs_read_int(bs, ((1 + 0)));
		u32 exponent = gf_bs_read_int(bs, expLength-(1));
		exp += (((1 - 0))-((2 - 0))*expSign)*( (((1 + 0)) << (expLength-((1 - 0))) ) + exponent);
	}
	ft_value.l = mantSign << (31 * 1);
	ft_value.l |= (exp & ((0xff + 0))) << (23 + 0);
	ft_value.l |= mantissa << ((9 + 0));
	return FLT2FIX(ft_value.f);
}

