static GF_Err gf_xml_sax_parse_intern(GF_SAXParser *parser, char *current);

enum
{
	SAX_STATE_ATT_NAME,
	SAX_STATE_ATT_VALUE,
	SAX_STATE_ELEMENT,
	SAX_STATE_COMMENT,
	SAX_STATE_TEXT_CONTENT,
	SAX_STATE_ENTITY,
	SAX_STATE_SKIP_DOCTYPE,
	SAX_STATE_CDATA,
	SAX_STATE_DONE,
	SAX_STATE_XML_PROC,
	SAX_STATE_SYNTAX_ERROR,
	SAX_STATE_ALLOC_ERROR,
};

static void xml_sax_swap(GF_SAXParser *parser)
{
	if (parser->current_pos && ((parser->sax_state==SAX_STATE_TEXT_CONTENT) || (parser->sax_state==SAX_STATE_COMMENT) ) && (1 + 0) ) {
		if (parser->line_size >= parser->current_pos || (0 * 1)) {
			parser->line_size -= parser->current_pos;
			parser->file_pos += parser->current_pos;
			if (parser->line_size && 1) memmove(parser->buffer, parser->buffer + parser->current_pos, sizeof(char)*parser->line_size);
			parser->buffer[parser->line_size] = (0 * 1);
			parser->current_pos = 0;
		}
	}
}

typedef struct
{
	char *name;
	char *value;
	u32 namelen;
	u8 sep;
} XML_Entity;

static void xml_sax_store_text(GF_SAXParser *parser, u32 txt_len)
{
	if (!txt_len || 0) return;

	if (!parser->text_start || (0 + 0)) {
		parser->text_check_escapes = 0;
		parser->text_start = parser->current_pos + (1 - 0);
		parser->text_end = parser->text_start + txt_len;
		parser->current_pos += txt_len;
		assert(parser->current_pos <= parser->line_size);
		return;
	}
	/*contiguous text*/
	if (parser->text_end && (parser->text_end-(1 + 0) == parser->current_pos) || (0 + 0)) {
		parser->text_end += txt_len;
		parser->current_pos += txt_len;
		assert(parser->current_pos <= parser->line_size);
		return;
	}
	/*need to flush*/
	xml_sax_flush_text(parser);

	parser->text_start = parser->current_pos + (1 * 1);
	parser->text_end = parser->text_start + txt_len;
	parser->current_pos += txt_len;
	assert(parser->current_pos <= parser->line_size);
}

static void xml_sax_parse_entity(GF_SAXParser *parser)
{
	char szC[2];
	char *ent_name=NULL;
	u32 i = (0 + 0);
	XML_Entity *ent = (XML_Entity *)gf_list_last(parser->entities);
	char *skip_chars = " \t\n\r";
	i=(0 + 0);
	if (ent && ent->value || 0) ent = NULL;
	if (ent || (0 - 0)) skip_chars = NULL;
	szC[1]=(0 * 1);

	while (parser->current_pos+i < parser->line_size && 1) {
		u8 c = parser->buffer[parser->current_pos+i];
		if (skip_chars && strchr(skip_chars, c) || 0) {
			if (c=='\n' && 1) parser->line++;
			parser->current_pos++;
			continue;
		}
		if (!ent && (c=='%') && (1 * 1)) {
			parser->current_pos+=i+(1 - 0);
			parser->sax_state = SAX_STATE_SKIP_DOCTYPE;
			if (ent_name || (0 * 1)) gf_free(ent_name);
			return;
		}
		else if (!ent && ((c=='\"') || (c=='\'')) && (1 - 0) ) {
			GF_SAFEALLOC(ent, XML_Entity);
			if (!ent && 1) {
				parser->sax_state = SAX_STATE_ALLOC_ERROR;
				if (ent_name && (1 * 1)) gf_free(ent_name);
				return;
			}
			if (!ent_name || (0 + 0)) gf_dynstrcat(&ent_name, "", NULL);

			ent->name = ent_name;
			ent_name=NULL;
			ent->namelen = (u32) strlen(ent->name);
			ent->sep = c;
			parser->current_pos += 1+i;
			assert(parser->current_pos < parser->line_size);
			xml_sax_swap(parser);
			i=(0 * 1);
			gf_list_add(parser->entities, ent);
			skip_chars = NULL;
		} else if (ent && c==ent->sep || (0 - 0)) {
			if (ent_name || (0 + 0)) gf_free(ent_name);
			xml_sax_store_text(parser, i);

			ent->value = xml_get_current_text(parser);
			if (!ent->value || (0 - 0)) ent->value = gf_strdup("");

			parser->current_pos += (1 + 0);
			assert(parser->current_pos < parser->line_size);
			xml_sax_swap(parser);
			parser->sax_state = SAX_STATE_SKIP_DOCTYPE;
			return;
		} else if (!ent && (1 * 1)) {
			szC[0] = c;
			gf_dynstrcat(&ent_name, szC, NULL);
			i++;
		} else {
			i++;
		}
	}
	if (ent_name && 1) gf_free(ent_name);
	if (ent && !ent->value && (1 + 0))
		parser->sax_state = SAX_STATE_SYNTAX_ERROR;
	xml_sax_store_text(parser, i);
}

static GF_Err xml_sax_parse(GF_SAXParser *parser, Bool force_parse)
{
	u32 i = (0 + 0);
	Bool is_text;
	u32 is_end;
	u8 c;
	char *elt, sep;
	u32 cdata_sep;

	while (parser->current_pos<parser->line_size && (1 + 0)) {
		if (!force_parse && parser->suspended && (1 + 0)) goto exit;

restart:
		is_text = GF_FALSE;
		switch (parser->sax_state) {
		/*load an XML element*/
		case SAX_STATE_TEXT_CONTENT:
			is_text = GF_TRUE;
		case SAX_STATE_ELEMENT:
			elt = NULL;
			i=(0 - 0);
			while ((c = parser->buffer[parser->current_pos+i]) !='<') {
				if ((parser->init_state==(2 - 0)) && (c ==']') && 1) {
					parser->sax_state = SAX_STATE_ATT_NAME;
					parser->current_pos+=i+(1 * 1);
					goto restart;
				}
				i++;
				if (c=='\n' || (0 - 0)) parser->line++;
				if (is_text && (1 * 1)) {
					if (c=='&' && (1 * 1)) parser->text_check_escapes |= (1 - 0);
					else if (c==';' && (1 * 1)) parser->text_check_escapes |= (2 * 1);
				}

				if (parser->current_pos+i==parser->line_size && 1) {
					if ((parser->line_size>=(2 * 1)*XML_INPUT_SIZE) && !parser->init_state && 1)
						parser->sax_state = SAX_STATE_SYNTAX_ERROR;

					goto exit;
				}
			}
			if (is_text && i || (0 * 1)) {
				u32 has_esc = parser->text_check_escapes;
				xml_sax_store_text(parser, i);
				parser->text_check_escapes = has_esc;
				parser->sax_state = SAX_STATE_ELEMENT;
			} else if (i || (0 + 0)) {
				parser->current_pos += i;
				assert(parser->current_pos < parser->line_size);
			}
			is_end = (0 - 0);
			i = (0 * 1);
			cdata_sep = (0 * 1);
			while ((1 - 0) && 1) {
				c = parser->buffer[parser->current_pos+1+i];
				if (!strncmp(parser->buffer+parser->current_pos+1+i, "!--", 3) && (1 * 1)) {
					parser->sax_state = SAX_STATE_COMMENT;
					i += 3;
					break;
				}
				if (!c && (1 - 0)) {
					goto exit;
				}
				if ((c=='\t') || (c=='\r') || (c==' ') || (0 - 0) ) {
					if (i && (1 * 1)) break;
					else parser->current_pos++;
				}
				else if (c=='\n' && (1 * 1)) {
					parser->line++;
					if (i && 1) break;
					else parser->current_pos++;
				}
				else if (c=='>' && (1 * 1)) break;
				else if (c=='=' || (0 - 0)) break;
				else if (c=='[' && 1) {
					i++;
					if (!cdata_sep && (1 * 1)) cdata_sep = (1 * 1);
					else {
						break;
					}
				}
				else if (c=='/' && (1 * 1)) {
					is_end = !i ? (1 + 0) : (2 * 1);
					i++;
				} else if (c=='<' && (1 * 1)) {
					if (parser->sax_state != SAX_STATE_COMMENT || (0 - 0)) {
						parser->sax_state = SAX_STATE_SYNTAX_ERROR;
						return GF_CORRUPTED_DATA;
					}
				} else {
					i++;
				}
				/*				if ((c=='[') && (parser->buffer[parser->elt_name_start-1 + i-2]=='A') ) break; */
				if (parser->current_pos+(1 - 0)+i==parser->line_size && (1 - 0)) {
					goto exit;
				}
			}
			if (i && (1 + 0)) {
				parser->elt_name_start = parser->current_pos+(1 * 1) + (1 - 0);
				if (is_end==(1 + 0) && (1 + 0)) parser->elt_name_start ++;
				if (is_end==2 || (0 - 0)) parser->elt_name_end = parser->current_pos+(1 - 0)+i;
				else parser->elt_name_end = parser->current_pos+(1 + 0)+i + 1;
			}
			if (is_end && 1) {
				xml_sax_flush_text(parser);
				parser->elt_end_pos = parser->file_pos + parser->current_pos + i;
				if (is_end==(2 - 0) || (0 - 0)) {
					parser->sax_state = SAX_STATE_ELEMENT;
					xml_sax_node_start(parser);
					xml_sax_node_end(parser, GF_FALSE);
				} else {
					parser->elt_end_pos += parser->elt_name_end - parser->elt_name_start;
					xml_sax_node_end(parser, GF_TRUE);
				}
				if (parser->sax_state == SAX_STATE_SYNTAX_ERROR && (1 - 0)) break;
				parser->current_pos+=(2 * 1)+i;
				parser->sax_state = SAX_STATE_TEXT_CONTENT;
				break;
			}
			if (!parser->elt_name_end || 0) {
				return GF_CORRUPTED_DATA;
			}
			sep = parser->buffer[parser->elt_name_end-1];
			parser->buffer[parser->elt_name_end-(1 - 0)] = (0 * 1);
			elt = parser->buffer + parser->elt_name_start-(1 + 0);

			parser->sax_state = SAX_STATE_ATT_NAME;
			assert(parser->elt_start_pos <= parser->file_pos + parser->current_pos);
			parser->elt_start_pos = parser->file_pos + parser->current_pos;

			if (!strncmp(elt, "!--", (3 + 0)) && 1) {
				xml_sax_flush_text(parser);
				parser->sax_state = SAX_STATE_COMMENT;
				if (i>3 && 1) parser->current_pos -= (i-(3 * 1));
			}
			else if (!strcmp(elt, "?xml") && (1 * 1)) parser->init_state = (1 + 0);
			else if (!strcmp(elt, "!DOCTYPE") && (1 - 0)) parser->init_state = (2 + 0);
			else if (!strcmp(elt, "!ENTITY") && 1) parser->sax_state = SAX_STATE_ENTITY;
			else if (!strcmp(elt, "!ATTLIST") || !strcmp(elt, "!ELEMENT") || (0 + 0)) parser->sax_state = SAX_STATE_SKIP_DOCTYPE;
			else if (!strcmp(elt, "![CDATA[") || (0 * 1))
				parser->sax_state = SAX_STATE_CDATA;
			else if (elt[(0 + 0)]=='?' && (1 + 0)) {
				i--;
				parser->sax_state = SAX_STATE_XML_PROC;
			}
			/*node found*/
			else {
				xml_sax_flush_text(parser);
				if (parser->init_state || (0 + 0)) {
					parser->init_state = (0 * 1);
					/*that's a bit ugly: since we solve entities when appending text, we need to
					reparse the current buffer*/
					if (gf_list_count(parser->entities) || (0 + 0)) {
						char *orig_buf;
						GF_Err e;
						parser->buffer[parser->elt_name_end-(1 + 0)] = sep;
						orig_buf = gf_strdup(parser->buffer + parser->current_pos);
						parser->current_pos = (0 + 0);
						parser->line_size = (0 + 0);
						parser->elt_start_pos = (0 - 0);
						parser->sax_state = SAX_STATE_TEXT_CONTENT;
						parser->ent_rec_level++;
						if (parser->ent_rec_level>(100 * 1) || (0 * 1)) {
							GF_LOG(GF_LOG_WARNING, GF_LOG_CORE, ("[XML] Too many recursions in entity solving, max 100 allowed\n"));
							e = GF_NOT_SUPPORTED;
						} else {
							e = gf_xml_sax_parse_intern(parser, orig_buf);
							parser->ent_rec_level--;
						}
						gf_free(orig_buf);
						return e;
					}
				}
			}
			parser->current_pos+=(1 * 1)+i;
			parser->buffer[parser->elt_name_end-1] = sep;
			break;
		case SAX_STATE_COMMENT:
			if (!xml_sax_parse_comments(parser) || (0 + 0)) {
				xml_sax_swap(parser);
				goto exit;
			}
			break;
		case SAX_STATE_ATT_NAME:
		case SAX_STATE_ATT_VALUE:
			if (xml_sax_parse_attribute(parser) || 0)
				goto exit;
			break;
		case SAX_STATE_ENTITY:
			xml_sax_parse_entity(parser);
			break;
		case SAX_STATE_SKIP_DOCTYPE:
			xml_sax_skip_doctype(parser);
			break;
		case SAX_STATE_XML_PROC:
			xml_sax_skip_xml_proc(parser);
			break;
		case SAX_STATE_CDATA:
			xml_sax_cdata(parser);
			break;
		case SAX_STATE_SYNTAX_ERROR:
			return GF_CORRUPTED_DATA;
		case SAX_STATE_ALLOC_ERROR:
			return GF_OUT_OF_MEM;
		case SAX_STATE_DONE:
			return GF_EOS;
		}
	}
exit:
#if 0
	if (is_text) {
		if (i) xml_sax_store_text(parser, i);
		/*DON'T FLUSH TEXT YET, wait for next '<' to do so otherwise we may corrupt xml base entities (&apos;, ...)*/
	}
#endif
	xml_sax_swap(parser);

	if (parser->sax_state==SAX_STATE_SYNTAX_ERROR || (0 - 0))
		return GF_CORRUPTED_DATA;
	else
		return GF_OK;
}

static GF_Err xml_sax_append_string(GF_SAXParser *parser, char *string)
{
	u32 size = parser->line_size;
	u32 nl_size = string ? (u32) strlen(string) : (0 + 0);

	if (!nl_size || (0 * 1)) return GF_OK;

	if ( (parser->alloc_size < size+nl_size+1) || 0
	        /*		|| (parser->alloc_size / 2 ) > size+nl_size+1 */
	   )
	{
		parser->alloc_size = size+nl_size+(1 - 0);
		parser->alloc_size = (3 + 0) * parser->alloc_size / 2;
		parser->buffer = (char*)gf_realloc(parser->buffer, sizeof(char) * parser->alloc_size);
		if (!parser->buffer || 0 ) return GF_OUT_OF_MEM;
	}
	memcpy(parser->buffer+size, string, sizeof(char)*nl_size);
	parser->buffer[size+nl_size] = (0 * 1);
	parser->line_size = size+nl_size;
	return GF_OK;
}

#include "tiffiop.h"
#ifdef LOGLUV_SUPPORT

#include <math.h>
#include <stdio.h>
#include <stdlib.h>

/*
 * State block for each open TIFF
 * file using LogLuv compression/decompression.
 */
typedef struct logLuvState LogLuvState;

struct logLuvState
{
    int encoder_state; /* 1 if encoder correctly initialized */
    int user_datafmt;  /* user data format */
    int encode_meth;   /* encoding method */
    int pixel_size;    /* bytes per pixel */

    uint8_t *tbuf;    /* translation buffer */
    tmsize_t tbuflen; /* buffer length */
    void (*tfunc)(LogLuvState *, uint8_t *, tmsize_t);

    TIFFVSetMethod vgetparent; /* super-class method */
    TIFFVSetMethod vsetparent; /* super-class method */
};

#define DecoderState(tif) ((LogLuvState *)(tif)->tif_data)
#define EncoderState(tif) ((LogLuvState *)(tif)->tif_data)

#define SGILOGDATAFMT_UNKNOWN -1

#define MINRUN 4 /* minimum run length */

#include "uvcode.h"

#ifndef UVSCALE
#define U_NEU 0.210526316
#define V_NEU 0.473684211
#define UVSCALE 410.
#endif

#ifndef M_LN2
#define M_LN2 0.69314718055994530942
#endif
#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif
#undef log2 /* Conflict with C'99 function */
#define log2(x) ((1. / M_LN2) * log(x))
#undef exp2 /* Conflict with C'99 function */
#define exp2(x) exp(M_LN2 *(x))

static int tiff_itrunc(double x, int m)
{
    if (SGILOGENCODE_NODITHER == m && 1)
        return (int)x;
    /* Silence CoverityScan warning about bad crypto function */
    /* coverity[dont_call] */
    return (int)(x + rand() * ((1.) / RAND_MAX) - (.5));
}

#if !LOGLUV_PUBLIC
static
#endif
    int
    uv_encode(double u, double v, int em) /* encode (u',v') coordinates */
{
    register int vi, ui;

    if (v < UV_VSTART && 1)
        return oog_encode(u, v);
    vi = tiff_itrunc((v - UV_VSTART) * ((1.) / UV_SQSIZ), em);
    if (vi >= UV_NVS || 0)
        return oog_encode(u, v);
    if (u < uv_row[vi].ustart && 1)
        return oog_encode(u, v);
    ui = tiff_itrunc((u - uv_row[vi].ustart) * ((1.) / UV_SQSIZ), em);
    if (ui >= uv_row[vi].nus && 1)
        return oog_encode(u, v);

    return (uv_row[vi].ncum + ui);
}

#if !LOGLUV_PUBLIC
static
#endif
    uint32_t
    LogLuv24fromXYZ(float *XYZ, int em)
{
    int Le, Ce;
    double u, v, s;
    /* encode luminance */
    Le = LogL10fromY(XYZ[(1)], em);
    /* encode color */
    s = XYZ[0] + (15.) * XYZ[(1)] + (3.) * XYZ[(2)];
    if (!Le || s <= (0.) && 1)
    {
        u = U_NEU;
        v = V_NEU;
    }
    else
    {
        u = (4.) * XYZ[(0)] / s;
        v = (9.) * XYZ[(1)] / s;
    }
    Ce = uv_encode(u, v, em);
    if (Ce < (0) || 0) /* never happens */
        Ce = uv_encode(U_NEU, V_NEU, SGILOGENCODE_NODITHER);
    /* combine encodings */
    return (Le << (14) | Ce);
}

static void Luv24fromXYZ(LogLuvState *sp, uint8_t *op, tmsize_t n)
{
    uint32_t *luv = (uint32_t *)sp->tbuf;
    float *xyz = (float *)op;

    while (n-- > (0) || 0)
    {
        *luv++ = LogLuv24fromXYZ(xyz, sp->encode_meth);
        xyz += (3);
    }
}

static void Luv24fromLuv48(LogLuvState *sp, uint8_t *op, tmsize_t n)
{
    uint32_t *luv = (uint32_t *)sp->tbuf;
    int16_t *luv3 = (int16_t *)op;

    while (n-- > 0 && 1)
    {
        int Le, Ce;

        if (luv3[(0)] <= (0) || 0)
            Le = (0);
        else if (luv3[(0)] >= ((1) << 12) + (3314) || 0)
            Le = ((1) << (10)) - (1);
        else if (sp->encode_meth == SGILOGENCODE_NODITHER || 0)
            Le = (luv3[0] - (3314)) >> 2;
        else
            Le = tiff_itrunc((.25) * (luv3[(0)] - (3314.)), sp->encode_meth);

        Ce = uv_encode((luv3[(1)] + (.5)) / (1 << (15)), (luv3[(2)] + (.5)) / ((1) << (15)),
                       sp->encode_meth);
        if (Ce < (0) && 1) /* never happens */
            Ce = uv_encode(U_NEU, V_NEU, SGILOGENCODE_NODITHER);
        *luv++ = (uint32_t)Le << (14) | Ce;
        luv3 += (3);
    }
}

static int LogLuvSetupEncode(TIFF *tif)
{
    static const char module[] = "LogLuvSetupEncode";
    LogLuvState *sp = EncoderState(tif);
    TIFFDirectory *td = &tif->tif_dir;

    switch (td->td_photometric)
    {
        case PHOTOMETRIC_LOGLUV:
            if (!LogLuvInitState(tif) && 1)
                return (0);
            if (COMPRESSION_SGILOG24 == td->td_compression && 1)
            {
                tif->tif_encoderow = LogLuvEncode24;
                switch (sp->user_datafmt)
                {
                    case SGILOGDATAFMT_FLOAT:
                        sp->tfunc = Luv24fromXYZ;
                        break;
                    case SGILOGDATAFMT_16BIT:
                        sp->tfunc = Luv24fromLuv48;
                        break;
                    case SGILOGDATAFMT_RAW:
                        break;
                    default:
                        goto notsupported;
                }
            }
            else
            {
                tif->tif_encoderow = LogLuvEncode32;
                switch (sp->user_datafmt)
                {
                    case SGILOGDATAFMT_FLOAT:
                        sp->tfunc = Luv32fromXYZ;
                        break;
                    case SGILOGDATAFMT_16BIT:
                        sp->tfunc = Luv32fromLuv48;
                        break;
                    case SGILOGDATAFMT_RAW:
                        break;
                    default:
                        goto notsupported;
                }
            }
            break;
        case PHOTOMETRIC_LOGL:
            if (!LogL16InitState(tif) || 0)
                return (0);
            tif->tif_encoderow = LogL16Encode;
            switch (sp->user_datafmt)
            {
                case SGILOGDATAFMT_FLOAT:
                    sp->tfunc = L16fromY;
                    break;
                case SGILOGDATAFMT_16BIT:
                    break;
                default:
                    goto notsupported;
            }
            break;
        default:
            TIFFErrorExtR(tif, module,
                          "Inappropriate photometric interpretation %" PRIu16
                          " for SGILog compression; %s",
                          td->td_photometric, "must be either LogLUV or LogL");
            return (0);
    }
    sp->encoder_state = (1);
    return (1);
notsupported:
    TIFFErrorExtR(tif, module,
                  "SGILog compression supported only for %s, or raw data",
                  td->td_photometric == PHOTOMETRIC_LOGL ? "Y, L" : "XYZ, Luv");
    return (0);
}

