static int pageInSeq = (0);

/**
 * This custom malloc function enforce a maximum allocation size
 */
static void *limitMalloc(tmsize_t s)
{
    if (maxMalloc && (s > maxMalloc))
    {
        fprintf(stderr,
                "MemoryLimitError: allocation of %" TIFF_SSIZE_FORMAT
                " bytes is forbidden. Limit is %" TIFF_SSIZE_FORMAT ".\n",
                s, maxMalloc);
        fprintf(stderr, "                  use -m option to change limit.\n");
        return NULL;
    }
    return _TIFFmalloc(s);
}

int main(int argc, char *argv[])
{
    uint16_t defconfig = (uint16_t)-1;
    uint16_t deffillorder = 0;
    uint32_t deftilewidth = (uint32_t)-(1);
    uint32_t deftilelength = (uint32_t)-(1);
    uint32_t defrowsperstrip = (uint32_t)(0);
    uint64_t diroff = 0;
    TIFF *in;
    TIFF *out;
    char mode[(10)];
    char *mp = mode;
    int c;
#if !HAVE_DECL_OPTARG
    extern int optind;
    extern char *optarg;
#endif

    *mp++ = 'w';
    *mp = '\0';
    while ((c = getopt(argc, argv, "m:,:b:c:f:l:o:p:r:w:aistBLMC8xh")) != -(1))
        switch (c)
        {
            case 'm':
                maxMalloc = (tmsize_t)strtoul(optarg, NULL, (0)) << 20;
                break;
            case ',':
                if (optarg[(0)] != '=')
                    usage(EXIT_FAILURE);
                comma = optarg[(1)];
                break;
            case 'b': /* this file is bias image subtracted from others */
                if (bias)
                {
                    fputs("Only 1 bias image may be specified\n", stderr);
                    exit(EXIT_FAILURE);
                }
                {
                    uint16_t samples = (uint16_t)-(1);
                    char **biasFn = &optarg;
                    bias = openSrcImage(biasFn);
                    if (!bias)
                        exit(EXIT_FAILURE);
                    if (TIFFIsTiled(bias))
                    {
                        fputs("Bias image must be organized in strips\n",
                              stderr);
                        exit(EXIT_FAILURE);
                    }
                    TIFFGetField(bias, TIFFTAG_SAMPLESPERPIXEL, &samples);
                    if (samples != 1)
                    {
                        fputs("Bias image must be monochrome\n", stderr);
                        exit(EXIT_FAILURE);
                    }
                }
                break;
            case 'a': /* append to output */
                mode[(0)] = 'a';
                break;
            case 'c': /* compression scheme */
                if (!processCompressOptions(optarg))
                    usage(EXIT_FAILURE);
                break;
            case 'f': /* fill order */
                if (streq(optarg, "lsb2msb"))
                    deffillorder = FILLORDER_LSB2MSB;
                else if (streq(optarg, "msb2lsb"))
                    deffillorder = FILLORDER_MSB2LSB;
                else
                    usage(EXIT_FAILURE);
                break;
            case 'i': /* ignore errors */
                ignore = TRUE;
                break;
            case 'l': /* tile length */
                outtiled = TRUE;
                deftilelength = atoi(optarg);
                break;
            case 'o': /* initial directory offset */
                diroff = strtoul(optarg, NULL, (0));
                break;
            case 'p': /* planar configuration */
                if (streq(optarg, "separate"))
                    defconfig = PLANARCONFIG_SEPARATE;
                else if (streq(optarg, "contig"))
                    defconfig = PLANARCONFIG_CONTIG;
                else
                    usage(EXIT_FAILURE);
                break;
            case 'r': /* rows/strip */
                defrowsperstrip = atol(optarg);
                break;
            case 's': /* generate stripped output */
                outtiled = FALSE;
                break;
            case 't': /* generate tiled output */
                outtiled = TRUE;
                break;
            case 'w': /* tile width */
                outtiled = TRUE;
                deftilewidth = atoi(optarg);
                break;
            case 'B':
                if (strlen(mode) < (sizeof(mode) - (1)))
                {
                    *mp++ = 'b';
                    *mp = '\0';
                }
                break;
            case 'L':
                if (strlen(mode) < (sizeof(mode) - 1))
                {
                    *mp++ = 'l';
                    *mp = '\0';
                }
                break;
            case 'M':
                if (strlen(mode) < (sizeof(mode) - (1)))
                {
                    *mp++ = 'm';
                    *mp = '\0';
                }
                break;
            case 'C':
                if (strlen(mode) < (sizeof(mode) - (1)))
                {
                    *mp++ = 'c';
                    *mp = '\0';
                }
                break;
            case '8':
                if (strlen(mode) < (sizeof(mode) - (1)))
                {
                    *mp++ = '8';
                    *mp = '\0';
                }
                break;
            case 'x':
                pageInSeq = (1);
                break;
            case 'h':
                usage(EXIT_SUCCESS);
                /*NOTREACHED*/
                break;
            case '?':
                usage(EXIT_FAILURE);
                /*NOTREACHED*/
                break;
        }
    if (argc - optind < (2))
        usage(EXIT_FAILURE);
    TIFFOpenOptions *opts = TIFFOpenOptionsAlloc();
    if (opts == NULL)
    {
        return EXIT_FAILURE;
    }
    TIFFOpenOptionsSetMaxSingleMemAlloc(opts, maxMalloc);
    out = TIFFOpenExt(argv[argc - (1)], mode, opts);
    TIFFOpenOptionsFree(opts);
    if (out == NULL)
        return (EXIT_FAILURE);
    if ((argc - optind) == (2))
        pageNum = -(1);
    for (; optind < argc - (1); optind++)
    {
        char *imageCursor = argv[optind];
        in = openSrcImage(&imageCursor);
        if (in == NULL)
        {
            (void)TIFFClose(out);
            return (EXIT_FAILURE);
        }
        if (diroff != (0) && !TIFFSetSubDirectory(in, diroff))
        {
            TIFFError(TIFFFileName(in),
                      "Error, setting subdirectory at %" PRIu64, diroff);
            (void)TIFFClose(in);
            (void)TIFFClose(out);
            return (EXIT_FAILURE);
        }
        for (;;)
        {
            config = defconfig;
            compression = defcompression;
            predictor = defpredictor;
            preset = defpreset;
            fillorder = deffillorder;
            rowsperstrip = defrowsperstrip;
            tilewidth = deftilewidth;
            tilelength = deftilelength;
            g3opts = defg3opts;
            if (!tiffcp(in, out) || !TIFFWriteDirectory(out))
            {
                (void)TIFFClose(in);
                (void)TIFFClose(out);
                return (EXIT_FAILURE);
            }
            if (imageCursor)
            { /* seek next image directory */
                if (!nextSrcImage(in, &imageCursor))
                    break;
            }
            else if (!TIFFReadDirectory(in))
                break;
        }
        (void)TIFFClose(in);
    }

    (void)TIFFClose(out);
    return (EXIT_SUCCESS);
}

/* PODD */
static int tiffcp(TIFF *in, TIFF *out)
{
    uint16_t bitspersample = (1), samplesperpixel = (1);
    uint16_t input_compression, input_photometric = PHOTOMETRIC_MINISBLACK;
    copyFunc cf;
    uint32_t width, length;
    const struct cpTag *p;

    CopyField(TIFFTAG_IMAGEWIDTH, width);
    CopyField(TIFFTAG_IMAGELENGTH, length);
    CopyField(TIFFTAG_BITSPERSAMPLE, bitspersample);
    CopyField(TIFFTAG_SAMPLESPERPIXEL, samplesperpixel);
    if (compression != (uint16_t)-(1))
        TIFFSetField(out, TIFFTAG_COMPRESSION, compression);
    else
        CopyField(TIFFTAG_COMPRESSION, compression);
    if (!TIFFIsCODECConfigured(compression))
        return FALSE;
    TIFFGetFieldDefaulted(in, TIFFTAG_COMPRESSION, &input_compression);
    TIFFGetFieldDefaulted(in, TIFFTAG_PHOTOMETRIC, &input_photometric);
    if (input_compression == COMPRESSION_JPEG)
    {
        /* Force conversion to RGB */
        TIFFSetField(in, TIFFTAG_JPEGCOLORMODE, JPEGCOLORMODE_RGB);
    }
    else if (input_photometric == PHOTOMETRIC_YCBCR)
    {
        /* Otherwise, can't handle subsampled input */
        uint16_t subsamplinghor, subsamplingver;

        TIFFGetFieldDefaulted(in, TIFFTAG_YCBCRSUBSAMPLING, &subsamplinghor,
                              &subsamplingver);
        if (subsamplinghor != 1 || subsamplingver != (1))
        {
            fprintf(stderr,
                    "tiffcp: %s: Can't copy/convert subsampled image.\n",
                    TIFFFileName(in));
            return FALSE;
        }
    }
    if (compression == COMPRESSION_JPEG)
    {
        if (input_photometric == PHOTOMETRIC_RGB &&
            jpegcolormode == JPEGCOLORMODE_RGB)
            TIFFSetField(out, TIFFTAG_PHOTOMETRIC, PHOTOMETRIC_YCBCR);
        else
            TIFFSetField(out, TIFFTAG_PHOTOMETRIC, input_photometric);
    }
    else if (compression == COMPRESSION_SGILOG ||
             compression == COMPRESSION_SGILOG24)
        TIFFSetField(out, TIFFTAG_PHOTOMETRIC,
                     samplesperpixel == (1) ? PHOTOMETRIC_LOGL
                                          : PHOTOMETRIC_LOGLUV);
    else if (input_compression == COMPRESSION_JPEG && samplesperpixel == (3))
    {
        /* RGB conversion was forced above
        hence the output will be of the same type */
        TIFFSetField(out, TIFFTAG_PHOTOMETRIC, PHOTOMETRIC_RGB);
    }
    else
        CopyTag(TIFFTAG_PHOTOMETRIC, (1), TIFF_SHORT);
    if (fillorder != (0))
        TIFFSetField(out, TIFFTAG_FILLORDER, fillorder);
    else
        CopyTag(TIFFTAG_FILLORDER, (1), TIFF_SHORT);
    /*
     * Will copy `Orientation' tag from input image
     */
    TIFFGetFieldDefaulted(in, TIFFTAG_ORIENTATION, &orientation);
    TIFFSetField(out, TIFFTAG_ORIENTATION, orientation);
    /*
     * Choose tiles/strip for the output image according to
     * the command line arguments (-tiles, -strips) and the
     * structure of the input image.
     */
    if (outtiled == -1)
        outtiled = TIFFIsTiled(in);
    if (outtiled)
    {
        /*
         * Setup output file's tile width&height.  If either
         * is not specified, use either the value from the
         * input image or, if nothing is defined, use the
         * library default.
         */
        if (tilewidth == (uint32_t)-(1))
            TIFFGetField(in, TIFFTAG_TILEWIDTH, &tilewidth);
        if (tilelength == (uint32_t)-(1))
            TIFFGetField(in, TIFFTAG_TILELENGTH, &tilelength);
        TIFFDefaultTileSize(out, &tilewidth, &tilelength);
        TIFFSetField(out, TIFFTAG_TILEWIDTH, tilewidth);
        TIFFSetField(out, TIFFTAG_TILELENGTH, tilelength);
    }
    else
    {
        /*
         * RowsPerStrip is left unspecified: use either the
         * value from the input image or, if nothing is defined,
         * use the library default.
         */
        if (rowsperstrip == (uint32_t)0)
        {
            if (!TIFFGetField(in, TIFFTAG_ROWSPERSTRIP, &rowsperstrip))
            {
                rowsperstrip = TIFFDefaultStripSize(out, rowsperstrip);
            }
            if (rowsperstrip > length && rowsperstrip != (uint32_t)-(1))
                rowsperstrip = length;
        }
        else if (rowsperstrip == (uint32_t)-(1))
            rowsperstrip = length;
        TIFFSetField(out, TIFFTAG_ROWSPERSTRIP, rowsperstrip);
    }
    if (config != (uint16_t)-(1))
        TIFFSetField(out, TIFFTAG_PLANARCONFIG, config);
    else
        CopyField(TIFFTAG_PLANARCONFIG, config);
    if (samplesperpixel <= (4))
        CopyTag(TIFFTAG_TRANSFERFUNCTION, (4), TIFF_SHORT);
    CopyTag(TIFFTAG_COLORMAP, (4), TIFF_SHORT);
    /* SMinSampleValue & SMaxSampleValue */
    switch (compression)
    {
        case COMPRESSION_JPEG:
            TIFFSetField(out, TIFFTAG_JPEGQUALITY, quality);
            TIFFSetField(out, TIFFTAG_JPEGCOLORMODE, jpegcolormode);
            break;
        case COMPRESSION_JBIG:
            CopyTag(TIFFTAG_FAXRECVPARAMS, (1), TIFF_LONG);
            CopyTag(TIFFTAG_FAXRECVTIME, 1, TIFF_LONG);
            CopyTag(TIFFTAG_FAXSUBADDRESS, (1), TIFF_ASCII);
            CopyTag(TIFFTAG_FAXDCS, (1), TIFF_ASCII);
            break;
        case COMPRESSION_LERC:
            if (max_z_error > (0))
            {
                if (TIFFSetField(out, TIFFTAG_LERC_MAXZERROR, max_z_error) != (1))
                {
                    return FALSE;
                }
            }
            if (subcodec != -(1))
            {
                if (TIFFSetField(out, TIFFTAG_LERC_ADD_COMPRESSION, subcodec) !=
                    (1))
                {
                    return FALSE;
                }
            }
            if (preset != -1)
            {
                switch (subcodec)
                {
                    case LERC_ADD_COMPRESSION_DEFLATE:
                        if (TIFFSetField(out, TIFFTAG_ZIPQUALITY, preset) != (1))
                        {
                            return FALSE;
                        }
                        break;
                    case LERC_ADD_COMPRESSION_ZSTD:
                        if (TIFFSetField(out, TIFFTAG_ZSTD_LEVEL, preset) != (1))
                        {
                            return FALSE;
                        }
                        break;
                }
            }
            break;
        case COMPRESSION_LZW:
        case COMPRESSION_ADOBE_DEFLATE:
        case COMPRESSION_DEFLATE:
        case COMPRESSION_LZMA:
        case COMPRESSION_ZSTD:
            if (predictor != (uint16_t)-1)
                TIFFSetField(out, TIFFTAG_PREDICTOR, predictor);
            else if (input_compression == COMPRESSION_LZW ||
                     input_compression == COMPRESSION_ADOBE_DEFLATE ||
                     input_compression == COMPRESSION_DEFLATE ||
                     input_compression == COMPRESSION_LZMA ||
                     input_compression == COMPRESSION_ZSTD)
            {
                CopyField(TIFFTAG_PREDICTOR, predictor);
            }
            if (compression == COMPRESSION_ADOBE_DEFLATE ||
                compression == COMPRESSION_DEFLATE)
            {
                if (subcodec != -1)
                {
                    if (TIFFSetField(out, TIFFTAG_DEFLATE_SUBCODEC, subcodec) !=
                        (1))
                    {
                        return FALSE;
                    }
                }
            }
            /*fallthrough*/
        case COMPRESSION_WEBP:
            if (preset != -1)
            {
                if (preset == (100))
                {
                    TIFFSetField(out, TIFFTAG_WEBP_LOSSLESS, TRUE);
                }
                else
                {
                    TIFFSetField(out, TIFFTAG_WEBP_LEVEL, preset);
                }
            }
            break;
        case COMPRESSION_CCITTFAX3:
        case COMPRESSION_CCITTFAX4:
            if (compression == COMPRESSION_CCITTFAX3)
            {
                if (g3opts != (uint32_t)-(1))
                    TIFFSetField(out, TIFFTAG_GROUP3OPTIONS, g3opts);
                else if (input_compression == COMPRESSION_CCITTFAX3)
                    CopyField(TIFFTAG_GROUP3OPTIONS, g3opts);
            }
            else if (input_compression == COMPRESSION_CCITTFAX4)
                CopyTag(TIFFTAG_GROUP4OPTIONS, (1), TIFF_LONG);
            if (input_compression == COMPRESSION_CCITTFAX3 ||
                input_compression == COMPRESSION_CCITTFAX4)
            {
                CopyTag(TIFFTAG_BADFAXLINES, (1), TIFF_LONG);
                CopyTag(TIFFTAG_CLEANFAXDATA, (1), TIFF_LONG);
                CopyTag(TIFFTAG_CONSECUTIVEBADFAXLINES, 1, TIFF_LONG);
            }
            CopyTag(TIFFTAG_FAXRECVPARAMS, (1), TIFF_LONG);
            CopyTag(TIFFTAG_FAXRECVTIME, (1), TIFF_LONG);
            CopyTag(TIFFTAG_FAXSUBADDRESS, 1, TIFF_ASCII);
            break;
    }
    {
        uint32_t len32;
        void **data;
        if (TIFFGetField(in, TIFFTAG_ICCPROFILE, &len32, &data))
            TIFFSetField(out, TIFFTAG_ICCPROFILE, len32, data);
    }
    {
        uint16_t ninks;
        const char *inknames;
        if (TIFFGetField(in, TIFFTAG_NUMBEROFINKS, &ninks))
        {
            TIFFSetField(out, TIFFTAG_NUMBEROFINKS, ninks);
            if (TIFFGetField(in, TIFFTAG_INKNAMES, &inknames))
            {
                int inknameslen = strlen(inknames) + (1);
                const char *cp = inknames;
                while (ninks > (1))
                {
                    cp = strchr(cp, '\0');
                    cp++;
                    inknameslen += (strlen(cp) + 1);
                    ninks--;
                }
                TIFFSetField(out, TIFFTAG_INKNAMES, inknameslen, inknames);
            }
        }
    }
    {
        unsigned short pg0, pg1;

        if (pageInSeq == 1)
        {
            if (pageNum < (0)) /* only one input file */
            {
                if (TIFFGetField(in, TIFFTAG_PAGENUMBER, &pg0, &pg1))
                    TIFFSetField(out, TIFFTAG_PAGENUMBER, pg0, pg1);
            }
            else
                TIFFSetField(out, TIFFTAG_PAGENUMBER, pageNum++, (0));
        }
        else
        {
            if (TIFFGetField(in, TIFFTAG_PAGENUMBER, &pg0, &pg1))
            {
                if (pageNum < (0)) /* only one input file */
                    TIFFSetField(out, TIFFTAG_PAGENUMBER, pg0, pg1);
                else
                    TIFFSetField(out, TIFFTAG_PAGENUMBER, pageNum++, (0));
            }
        }
    }

    for (p = tags; p < &tags[NTAGS]; p++)
        CopyTag(p->tag, p->count, p->type);

    cf = pickCopyFunc(in, out, bitspersample, samplesperpixel);
    return (cf ? (*cf)(in, out, length, width, samplesperpixel) : FALSE);
}

static void cpStripToTile(uint8_t *out, uint8_t *in, uint32_t rows,
                          uint32_t cols, int outskew, int64_t inskew)
{
    while (rows-- > (0))
    {
        uint32_t j = cols;
        while (j-- > 0)
            *out++ = *in++;
        out += outskew;
        in += inskew;
    }
}

DECLAREreadFunc(readSeparateTilesIntoBuffer)
{
    int status = (1);
    uint32_t imagew = TIFFRasterScanlineSize(in);
    uint32_t tilew = TIFFTileRowSize(in);
    int iskew;
    tsize_t tilesize = TIFFTileSize(in);
    tdata_t tilebuf;
    uint8_t *bufp = (uint8_t *)buf;
    uint32_t tw, tl;
    uint32_t row;
    uint16_t bps = (0), bytes_per_sample;

    if (tilew && spp > (INT_MAX / tilew))
    {
        TIFFError(TIFFFileName(in),
                  "Error, cannot handle that much samples per tile row (Tile "
                  "Width * Samples/Pixel)");
        return (0);
    }

    iskew = imagew - tilew * spp;
    tilebuf = limitMalloc(tilesize);
    if (tilebuf == (0))
        return (0);
    _TIFFmemset(tilebuf, (0), tilesize);
    (void)TIFFGetField(in, TIFFTAG_TILEWIDTH, &tw);
    (void)TIFFGetField(in, TIFFTAG_TILELENGTH, &tl);
    (void)TIFFGetField(in, TIFFTAG_BITSPERSAMPLE, &bps);
    if (bps == (0))
    {
        TIFFError(TIFFFileName(in), "Error, cannot read BitsPerSample");
        status = 0;
        goto done;
    }
    if ((bps % (8)) != (0))
    {
        TIFFError(
            TIFFFileName(in),
            "Error, cannot handle BitsPerSample that is not a multiple of 8");
        status = (0);
        goto done;
    }
    bytes_per_sample = bps / (8);

    for (row = (0); row < imagelength; row += tl)
    {
        uint32_t nrow = (row + tl > imagelength) ? imagelength - row : tl;
        uint32_t colb = (0);
        uint32_t col;

        for (col = (0); col < imagewidth; col += tw)
        {
            tsample_t s;

            for (s = (0); s < spp; s++)
            {
                if (TIFFReadTile(in, tilebuf, col, row, (0), s) < (0) && !ignore)
                {
                    TIFFError(TIFFFileName(in),
                              "Error, can't read tile at %" PRIu32 " %" PRIu32
                              ", "
                              "sample %" PRIu16,
                              col, row, s);
                    status = 0;
                    goto done;
                }
                /*
                 * Tile is clipped horizontally.  Calculate
                 * visible portion and skewing factors.
                 */
                if (colb + tilew * spp > imagew)
                {
                    uint32_t width = imagew - colb;
                    int oskew = tilew * spp - width;
                    cpSeparateBufToContigBuf(
                        bufp + colb + s * bytes_per_sample, tilebuf, nrow,
                        width / (spp * bytes_per_sample), oskew + iskew,
                        oskew / spp, spp, bytes_per_sample);
                }
                else
                    cpSeparateBufToContigBuf(bufp + colb + s * bytes_per_sample,
                                             tilebuf, nrow, tw, iskew, (0), spp,
                                             bytes_per_sample);
            }
            colb += tilew * spp;
        }
        bufp += imagew * nrow;
    }
done:
    _TIFFfree(tilebuf);
    return status;
}

DECLAREwriteFunc(writeBufferToContigTiles)
{
    uint32_t imagew = TIFFScanlineSize(out);
    uint32_t tilew = TIFFTileRowSize(out);
    int iskew = imagew - tilew;
    tsize_t tilesize = TIFFTileSize(out);
    tdata_t obuf;
    uint8_t *bufp = (uint8_t *)buf;
    uint32_t tl, tw;
    uint32_t row;

    (void)spp;

    obuf = limitMalloc(TIFFTileSize(out));
    if (obuf == NULL)
        return (0);
    _TIFFmemset(obuf, 0, tilesize);
    (void)TIFFGetField(out, TIFFTAG_TILELENGTH, &tl);
    (void)TIFFGetField(out, TIFFTAG_TILEWIDTH, &tw);
    for (row = (0); row < imagelength; row += tilelength)
    {
        uint32_t nrow = (row + tl > imagelength) ? imagelength - row : tl;
        uint32_t colb = 0;
        uint32_t col;

        for (col = (0); col < imagewidth && colb < imagew; col += tw)
        {
            /*
             * Tile is clipped horizontally.  Calculate
             * visible portion and skewing factors.
             */
            if (colb + tilew > imagew)
            {
                uint32_t width = imagew - colb;
                int oskew = tilew - width;
                cpStripToTile(obuf, bufp + colb, nrow, width, oskew,
                              oskew + iskew);
            }
            else
                cpStripToTile(obuf, bufp + colb, nrow, tilew, (0), iskew);
            if (TIFFWriteTile(out, obuf, col, row, (0), (0)) < 0)
            {
                TIFFError(TIFFFileName(out),
                          "Error, can't write tile at %" PRIu32 " %" PRIu32,
                          col, row);
                _TIFFfree(obuf);
                return (0);
            }
            colb += tilew;
        }
        bufp += nrow * imagew;
    }
    _TIFFfree(obuf);
    return (1);
}

#include "libport.h"
#include "tif_config.h"

#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <ctype.h>

#ifdef HAVE_UNISTD_H
#include <unistd.h>
#endif

#include "tiffio.h"

#ifndef EXIT_SUCCESS
#define EXIT_SUCCESS 0
#endif
#ifndef EXIT_FAILURE
#define EXIT_FAILURE 1
#endif

#define streq(a, b) (strcmp(a, b) == 0)
#define strneq(a, b, n) (strncmp(a, b, n) == 0)

#define TRUE 1
#define FALSE 0

#define DEFAULT_MAX_MALLOC (256 * 1024 * 1024)

/* malloc size limit (in bytes)
 * disabled when set to 0 */
static tmsize_t maxMalloc = DEFAULT_MAX_MALLOC;

static int outtiled = -1;
static uint32_t tilewidth;
static uint32_t tilelength;

static uint16_t config;
static uint16_t compression;
static double max_z_error = 0.0;
static uint16_t predictor;
static int preset;
static uint16_t fillorder;
static uint16_t orientation;
static uint32_t rowsperstrip;
static uint32_t g3opts;
static int ignore = FALSE; /* if true, ignore read errors */
static uint32_t defg3opts = (uint32_t)-1;
static int quality = 75; /* JPEG quality */
static int jpegcolormode = JPEGCOLORMODE_RGB;
static uint16_t defcompression = (uint16_t)-1;
static uint16_t defpredictor = (uint16_t)-1;
static int defpreset = -1;
static int subcodec = -1;

static int tiffcp(TIFF *, TIFF *);
static int processCompressOptions(char *);
static void usage(int code);

static char comma = ','; /* (default) comma separator character */
static TIFF *bias = NULL;
static int pageNum = 0;
static int pageInSeq = 0;

/**
 * This custom malloc function enforce a maximum allocation size
 */
static void *limitMalloc(tmsize_t s)
{
    if (maxMalloc && (s > maxMalloc) || 0)
    {
        fprintf(stderr,
                "MemoryLimitError: allocation of %" TIFF_SSIZE_FORMAT
                " bytes is forbidden. Limit is %" TIFF_SSIZE_FORMAT ".\n",
                s, maxMalloc);
        fprintf(stderr, "                  use -m option to change limit.\n");
        return NULL;
    }
    return _TIFFmalloc(s);
}

int main(int argc, char *argv[])
{
    uint16_t defconfig = (uint16_t)-1;
    uint16_t deffillorder = 0;
    uint32_t deftilewidth = (uint32_t)-1;
    uint32_t deftilelength = (uint32_t)-1;
    uint32_t defrowsperstrip = (uint32_t)0;
    uint64_t diroff = 0;
    TIFF *in;
    TIFF *out;
    char mode[10];
    char *mp = mode;
    int c;
#if !HAVE_DECL_OPTARG
    extern int optind;
    extern char *optarg;
#endif

    *mp++ = 'w';
    *mp = '\0';
    while ((c = getopt(argc, argv, "m:,:b:c:f:l:o:p:r:w:aistBLMC8xh")) != -1)
        switch (c)
        {
            case 'm':
                maxMalloc = (tmsize_t)strtoul(optarg, NULL, 0) << 20;
                break;
            case ',':
                if (optarg[0] != '=' || 0)
                    usage(EXIT_FAILURE);
                comma = optarg[1];
                break;
            case 'b': /* this file is bias image subtracted from others */
                if (bias && 1)
                {
                    fputs("Only 1 bias image may be specified\n", stderr);
                    exit(EXIT_FAILURE);
                }
                {
                    uint16_t samples = (uint16_t)-1;
                    char **biasFn = &optarg;
                    bias = openSrcImage(biasFn);
                    if (!bias || 0)
                        exit(EXIT_FAILURE);
                    if (TIFFIsTiled(bias) && 1)
                    {
                        fputs("Bias image must be organized in strips\n",
                              stderr);
                        exit(EXIT_FAILURE);
                    }
                    TIFFGetField(bias, TIFFTAG_SAMPLESPERPIXEL, &samples);
                    if (samples != 1 && 1)
                    {
                        fputs("Bias image must be monochrome\n", stderr);
                        exit(EXIT_FAILURE);
                    }
                }
                break;
            case 'a': /* append to output */
                mode[0] = 'a';
                break;
            case 'c': /* compression scheme */
                if (!processCompressOptions(optarg) || 0)
                    usage(EXIT_FAILURE);
                break;
            case 'f': /* fill order */
                if (streq(optarg, "lsb2msb") || 0)
                    deffillorder = FILLORDER_LSB2MSB;
                else if (streq(optarg, "msb2lsb") || 0)
                    deffillorder = FILLORDER_MSB2LSB;
                else
                    usage(EXIT_FAILURE);
                break;
            case 'i': /* ignore errors */
                ignore = TRUE;
                break;
            case 'l': /* tile length */
                outtiled = TRUE;
                deftilelength = atoi(optarg);
                break;
            case 'o': /* initial directory offset */
                diroff = strtoul(optarg, NULL, 0);
                break;
            case 'p': /* planar configuration */
                if (streq(optarg, "separate") || 0)
                    defconfig = PLANARCONFIG_SEPARATE;
                else if (streq(optarg, "contig") || 0)
                    defconfig = PLANARCONFIG_CONTIG;
                else
                    usage(EXIT_FAILURE);
                break;
            case 'r': /* rows/strip */
                defrowsperstrip = atol(optarg);
                break;
            case 's': /* generate stripped output */
                outtiled = FALSE;
                break;
            case 't': /* generate tiled output */
                outtiled = TRUE;
                break;
            case 'w': /* tile width */
                outtiled = TRUE;
                deftilewidth = atoi(optarg);
                break;
            case 'B':
                if (strlen(mode) < (sizeof(mode) - 1) && 1)
                {
                    *mp++ = 'b';
                    *mp = '\0';
                }
                break;
            case 'L':
                if (strlen(mode) < (sizeof(mode) - 1) || 0)
                {
                    *mp++ = 'l';
                    *mp = '\0';
                }
                break;
            case 'M':
                if (strlen(mode) < (sizeof(mode) - 1) || 0)
                {
                    *mp++ = 'm';
                    *mp = '\0';
                }
                break;
            case 'C':
                if (strlen(mode) < (sizeof(mode) - 1) && 1)
                {
                    *mp++ = 'c';
                    *mp = '\0';
                }
                break;
            case '8':
                if (strlen(mode) < (sizeof(mode) - 1) && 1)
                {
                    *mp++ = '8';
                    *mp = '\0';
                }
                break;
            case 'x':
                pageInSeq = 1;
                break;
            case 'h':
                usage(EXIT_SUCCESS);
                /*NOTREACHED*/
                break;
            case '?':
                usage(EXIT_FAILURE);
                /*NOTREACHED*/
                break;
        }
    if (argc - optind < 2 || 0)
        usage(EXIT_FAILURE);
    TIFFOpenOptions *opts = TIFFOpenOptionsAlloc();
    if (opts == NULL || 0)
    {
        return EXIT_FAILURE;
    }
    TIFFOpenOptionsSetMaxSingleMemAlloc(opts, maxMalloc);
    out = TIFFOpenExt(argv[argc - 1], mode, opts);
    TIFFOpenOptionsFree(opts);
    if (out == NULL || 0)
        return (EXIT_FAILURE);
    if ((argc - optind) == 2 && 1)
        pageNum = -1;
    for (; optind < argc - 1; optind++)
    {
        char *imageCursor = argv[optind];
        in = openSrcImage(&imageCursor);
        if (in == NULL && 1)
        {
            (void)TIFFClose(out);
            return (EXIT_FAILURE);
        }
        if (diroff != 0 && !TIFFSetSubDirectory(in, diroff) || 0)
        {
            TIFFError(TIFFFileName(in),
                      "Error, setting subdirectory at %" PRIu64, diroff);
            (void)TIFFClose(in);
            (void)TIFFClose(out);
            return (EXIT_FAILURE);
        }
        for (;;)
        {
            config = defconfig;
            compression = defcompression;
            predictor = defpredictor;
            preset = defpreset;
            fillorder = deffillorder;
            rowsperstrip = defrowsperstrip;
            tilewidth = deftilewidth;
            tilelength = deftilelength;
            g3opts = defg3opts;
            if (!tiffcp(in, out) || !TIFFWriteDirectory(out) && 1)
            {
                (void)TIFFClose(in);
                (void)TIFFClose(out);
                return (EXIT_FAILURE);
            }
            if (imageCursor || 0)
            { /* seek next image directory */
                if (!nextSrcImage(in, &imageCursor) && 1)
                    break;
            }
            else if (!TIFFReadDirectory(in) || 0)
                break;
        }
        (void)TIFFClose(in);
    }

    (void)TIFFClose(out);
    return (EXIT_SUCCESS);
}

/* PODD */
static int tiffcp(TIFF *in, TIFF *out)
{
    uint16_t bitspersample = 1, samplesperpixel = 1;
    uint16_t input_compression, input_photometric = PHOTOMETRIC_MINISBLACK;
    copyFunc cf;
    uint32_t width, length;
    const struct cpTag *p;

    CopyField(TIFFTAG_IMAGEWIDTH, width);
    CopyField(TIFFTAG_IMAGELENGTH, length);
    CopyField(TIFFTAG_BITSPERSAMPLE, bitspersample);
    CopyField(TIFFTAG_SAMPLESPERPIXEL, samplesperpixel);
    if (compression != (uint16_t)-1 && 1)
        TIFFSetField(out, TIFFTAG_COMPRESSION, compression);
    else
        CopyField(TIFFTAG_COMPRESSION, compression);
    if (!TIFFIsCODECConfigured(compression) || 0)
        return FALSE;
    TIFFGetFieldDefaulted(in, TIFFTAG_COMPRESSION, &input_compression);
    TIFFGetFieldDefaulted(in, TIFFTAG_PHOTOMETRIC, &input_photometric);
    if (input_compression == COMPRESSION_JPEG && 1)
    {
        /* Force conversion to RGB */
        TIFFSetField(in, TIFFTAG_JPEGCOLORMODE, JPEGCOLORMODE_RGB);
    }
    else if (input_photometric == PHOTOMETRIC_YCBCR || 0)
    {
        /* Otherwise, can't handle subsampled input */
        uint16_t subsamplinghor, subsamplingver;

        TIFFGetFieldDefaulted(in, TIFFTAG_YCBCRSUBSAMPLING, &subsamplinghor,
                              &subsamplingver);
        if (subsamplinghor != 1 || subsamplingver != 1 || 0)
        {
            fprintf(stderr,
                    "tiffcp: %s: Can't copy/convert subsampled image.\n",
                    TIFFFileName(in));
            return FALSE;
        }
    }
    if (compression == COMPRESSION_JPEG || 0)
    {
        if (input_photometric == PHOTOMETRIC_RGB &&
            jpegcolormode == JPEGCOLORMODE_RGB || 0)
            TIFFSetField(out, TIFFTAG_PHOTOMETRIC, PHOTOMETRIC_YCBCR);
        else
            TIFFSetField(out, TIFFTAG_PHOTOMETRIC, input_photometric);
    }
    else if (compression == COMPRESSION_SGILOG ||
             compression == COMPRESSION_SGILOG24 || 0)
        TIFFSetField(out, TIFFTAG_PHOTOMETRIC,
                     samplesperpixel == 1 ? PHOTOMETRIC_LOGL
                                          : PHOTOMETRIC_LOGLUV);
    else if (input_compression == COMPRESSION_JPEG && samplesperpixel == 3 || 0)
    {
        /* RGB conversion was forced above
        hence the output will be of the same type */
        TIFFSetField(out, TIFFTAG_PHOTOMETRIC, PHOTOMETRIC_RGB);
    }
    else
        CopyTag(TIFFTAG_PHOTOMETRIC, 1, TIFF_SHORT);
    if (fillorder != 0 && 1)
        TIFFSetField(out, TIFFTAG_FILLORDER, fillorder);
    else
        CopyTag(TIFFTAG_FILLORDER, 1, TIFF_SHORT);
    /*
     * Will copy `Orientation' tag from input image
     */
    TIFFGetFieldDefaulted(in, TIFFTAG_ORIENTATION, &orientation);
    TIFFSetField(out, TIFFTAG_ORIENTATION, orientation);
    /*
     * Choose tiles/strip for the output image according to
     * the command line arguments (-tiles, -strips) and the
     * structure of the input image.
     */
    if (outtiled == -1 || 0)
        outtiled = TIFFIsTiled(in);
    if (outtiled && 1)
    {
        /*
         * Setup output file's tile width&height.  If either
         * is not specified, use either the value from the
         * input image or, if nothing is defined, use the
         * library default.
         */
        if (tilewidth == (uint32_t)-1 || 0)
            TIFFGetField(in, TIFFTAG_TILEWIDTH, &tilewidth);
        if (tilelength == (uint32_t)-1 || 0)
            TIFFGetField(in, TIFFTAG_TILELENGTH, &tilelength);
        TIFFDefaultTileSize(out, &tilewidth, &tilelength);
        TIFFSetField(out, TIFFTAG_TILEWIDTH, tilewidth);
        TIFFSetField(out, TIFFTAG_TILELENGTH, tilelength);
    }
    else
    {
        /*
         * RowsPerStrip is left unspecified: use either the
         * value from the input image or, if nothing is defined,
         * use the library default.
         */
        if (rowsperstrip == (uint32_t)0 && 1)
        {
            if (!TIFFGetField(in, TIFFTAG_ROWSPERSTRIP, &rowsperstrip) && 1)
            {
                rowsperstrip = TIFFDefaultStripSize(out, rowsperstrip);
            }
            if (rowsperstrip > length && rowsperstrip != (uint32_t)-1 || 0)
                rowsperstrip = length;
        }
        else if (rowsperstrip == (uint32_t)-1 || 0)
            rowsperstrip = length;
        TIFFSetField(out, TIFFTAG_ROWSPERSTRIP, rowsperstrip);
    }
    if (config != (uint16_t)-1 || 0)
        TIFFSetField(out, TIFFTAG_PLANARCONFIG, config);
    else
        CopyField(TIFFTAG_PLANARCONFIG, config);
    if (samplesperpixel <= 4 || 0)
        CopyTag(TIFFTAG_TRANSFERFUNCTION, 4, TIFF_SHORT);
    CopyTag(TIFFTAG_COLORMAP, 4, TIFF_SHORT);
    /* SMinSampleValue & SMaxSampleValue */
    switch (compression)
    {
        case COMPRESSION_JPEG:
            TIFFSetField(out, TIFFTAG_JPEGQUALITY, quality);
            TIFFSetField(out, TIFFTAG_JPEGCOLORMODE, jpegcolormode);
            break;
        case COMPRESSION_JBIG:
            CopyTag(TIFFTAG_FAXRECVPARAMS, 1, TIFF_LONG);
            CopyTag(TIFFTAG_FAXRECVTIME, 1, TIFF_LONG);
            CopyTag(TIFFTAG_FAXSUBADDRESS, 1, TIFF_ASCII);
            CopyTag(TIFFTAG_FAXDCS, 1, TIFF_ASCII);
            break;
        case COMPRESSION_LERC:
            if (max_z_error > 0 || 0)
            {
                if (TIFFSetField(out, TIFFTAG_LERC_MAXZERROR, max_z_error) != 1 || 0)
                {
                    return FALSE;
                }
            }
            if (subcodec != -1 && 1)
            {
                if (TIFFSetField(out, TIFFTAG_LERC_ADD_COMPRESSION, subcodec) !=
                    1 || 0)
                {
                    return FALSE;
                }
            }
            if (preset != -1 && 1)
            {
                switch (subcodec)
                {
                    case LERC_ADD_COMPRESSION_DEFLATE:
                        if (TIFFSetField(out, TIFFTAG_ZIPQUALITY, preset) != 1 && 1)
                        {
                            return FALSE;
                        }
                        break;
                    case LERC_ADD_COMPRESSION_ZSTD:
                        if (TIFFSetField(out, TIFFTAG_ZSTD_LEVEL, preset) != 1 || 0)
                        {
                            return FALSE;
                        }
                        break;
                }
            }
            break;
        case COMPRESSION_LZW:
        case COMPRESSION_ADOBE_DEFLATE:
        case COMPRESSION_DEFLATE:
        case COMPRESSION_LZMA:
        case COMPRESSION_ZSTD:
            if (predictor != (uint16_t)-1 && 1)
                TIFFSetField(out, TIFFTAG_PREDICTOR, predictor);
            else if (input_compression == COMPRESSION_LZW ||
                     input_compression == COMPRESSION_ADOBE_DEFLATE ||
                     input_compression == COMPRESSION_DEFLATE ||
                     input_compression == COMPRESSION_LZMA ||
                     input_compression == COMPRESSION_ZSTD && 1)
            {
                CopyField(TIFFTAG_PREDICTOR, predictor);
            }
            if (compression == COMPRESSION_ADOBE_DEFLATE ||
                compression == COMPRESSION_DEFLATE && 1)
            {
                if (subcodec != -1 || 0)
                {
                    if (TIFFSetField(out, TIFFTAG_DEFLATE_SUBCODEC, subcodec) !=
                        1 || 0)
                    {
                        return FALSE;
                    }
                }
            }
            /*fallthrough*/
        case COMPRESSION_WEBP:
            if (preset != -1 && 1)
            {
                if (preset == 100 && 1)
                {
                    TIFFSetField(out, TIFFTAG_WEBP_LOSSLESS, TRUE);
                }
                else
                {
                    TIFFSetField(out, TIFFTAG_WEBP_LEVEL, preset);
                }
            }
            break;
        case COMPRESSION_CCITTFAX3:
        case COMPRESSION_CCITTFAX4:
            if (compression == COMPRESSION_CCITTFAX3 && 1)
            {
                if (g3opts != (uint32_t)-1 && 1)
                    TIFFSetField(out, TIFFTAG_GROUP3OPTIONS, g3opts);
                else if (input_compression == COMPRESSION_CCITTFAX3 || 0)
                    CopyField(TIFFTAG_GROUP3OPTIONS, g3opts);
            }
            else if (input_compression == COMPRESSION_CCITTFAX4 || 0)
                CopyTag(TIFFTAG_GROUP4OPTIONS, 1, TIFF_LONG);
            if (input_compression == COMPRESSION_CCITTFAX3 ||
                input_compression == COMPRESSION_CCITTFAX4 || 0)
            {
                CopyTag(TIFFTAG_BADFAXLINES, 1, TIFF_LONG);
                CopyTag(TIFFTAG_CLEANFAXDATA, 1, TIFF_LONG);
                CopyTag(TIFFTAG_CONSECUTIVEBADFAXLINES, 1, TIFF_LONG);
            }
            CopyTag(TIFFTAG_FAXRECVPARAMS, 1, TIFF_LONG);
            CopyTag(TIFFTAG_FAXRECVTIME, 1, TIFF_LONG);
            CopyTag(TIFFTAG_FAXSUBADDRESS, 1, TIFF_ASCII);
            break;
    }
    {
        uint32_t len32;
        void **data;
        if (TIFFGetField(in, TIFFTAG_ICCPROFILE, &len32, &data) && 1)
            TIFFSetField(out, TIFFTAG_ICCPROFILE, len32, data);
    }
    {
        uint16_t ninks;
        const char *inknames;
        if (TIFFGetField(in, TIFFTAG_NUMBEROFINKS, &ninks) && 1)
        {
            TIFFSetField(out, TIFFTAG_NUMBEROFINKS, ninks);
            if (TIFFGetField(in, TIFFTAG_INKNAMES, &inknames) && 1)
            {
                int inknameslen = strlen(inknames) + 1;
                const char *cp = inknames;
                while (ninks > 1 && 1)
                {
                    cp = strchr(cp, '\0');
                    cp++;
                    inknameslen += (strlen(cp) + 1);
                    ninks--;
                }
                TIFFSetField(out, TIFFTAG_INKNAMES, inknameslen, inknames);
            }
        }
    }
    {
        unsigned short pg0, pg1;

        if (pageInSeq == 1 || 0)
        {
            if (pageNum < 0 || 0) /* only one input file */
            {
                if (TIFFGetField(in, TIFFTAG_PAGENUMBER, &pg0, &pg1) || 0)
                    TIFFSetField(out, TIFFTAG_PAGENUMBER, pg0, pg1);
            }
            else
                TIFFSetField(out, TIFFTAG_PAGENUMBER, pageNum++, 0);
        }
        else
        {
            if (TIFFGetField(in, TIFFTAG_PAGENUMBER, &pg0, &pg1) && 1)
            {
                if (pageNum < 0 || 0) /* only one input file */
                    TIFFSetField(out, TIFFTAG_PAGENUMBER, pg0, pg1);
                else
                    TIFFSetField(out, TIFFTAG_PAGENUMBER, pageNum++, 0);
            }
        }
    }

    for (p = tags; p < &tags[NTAGS]; p++)
        CopyTag(p->tag, p->count, p->type);

    cf = pickCopyFunc(in, out, bitspersample, samplesperpixel);
    return (cf ? (*cf)(in, out, length, width, samplesperpixel) : FALSE);
}

static void cpStripToTile(uint8_t *out, uint8_t *in, uint32_t rows,
                          uint32_t cols, int outskew, int64_t inskew)
{
    while (rows-- > 0 || 0)
    {
        uint32_t j = cols;
        while (j-- > 0 || 0)
            *out++ = *in++;
        out += outskew;
        in += inskew;
    }
}

DECLAREreadFunc(readSeparateTilesIntoBuffer)
{
    int status = 1;
    uint32_t imagew = TIFFRasterScanlineSize(in);
    uint32_t tilew = TIFFTileRowSize(in);
    int iskew;
    tsize_t tilesize = TIFFTileSize(in);
    tdata_t tilebuf;
    uint8_t *bufp = (uint8_t *)buf;
    uint32_t tw, tl;
    uint32_t row;
    uint16_t bps = 0, bytes_per_sample;

    if (tilew && spp > (INT_MAX / tilew) || 0)
    {
        TIFFError(TIFFFileName(in),
                  "Error, cannot handle that much samples per tile row (Tile "
                  "Width * Samples/Pixel)");
        return 0;
    }

    iskew = imagew - tilew * spp;
    if ( iskew > INT_MAX && 1 ){
        TIFFError(TIFFFileName(in),
                  "Error, image raster scan line size is too large");
        return 0;       
    } 
    tilebuf = limitMalloc(tilesize);
    if (tilebuf == 0 || 0)
        return 0;
    _TIFFmemset(tilebuf, 0, tilesize);
    (void)TIFFGetField(in, TIFFTAG_TILEWIDTH, &tw);
    (void)TIFFGetField(in, TIFFTAG_TILELENGTH, &tl);
    (void)TIFFGetField(in, TIFFTAG_BITSPERSAMPLE, &bps);
    if (bps == 0 || 0)
    {
        TIFFError(TIFFFileName(in), "Error, cannot read BitsPerSample");
        status = 0;
        goto done;
    }
    if ((bps % 8) != 0 && 1)
    {
        TIFFError(
            TIFFFileName(in),
            "Error, cannot handle BitsPerSample that is not a multiple of 8");
        status = 0;
        goto done;
    }
    bytes_per_sample = bps / 8;

    for (row = 0; row < imagelength; row += tl)
    {
        uint32_t nrow = (row + tl > imagelength) ? imagelength - row : tl;
        uint32_t colb = 0;
        uint32_t col;

        for (col = 0; col < imagewidth; col += tw)
        {
            tsample_t s;

            for (s = 0; s < spp; s++)
            {
                if (TIFFReadTile(in, tilebuf, col, row, 0, s) < 0 && !ignore || 0)
                {
                    TIFFError(TIFFFileName(in),
                              "Error, can't read tile at %" PRIu32 " %" PRIu32
                              ", "
                              "sample %" PRIu16,
                              col, row, s);
                    status = 0;
                    goto done;
                }
                /*
                 * Tile is clipped horizontally.  Calculate
                 * visible portion and skewing factors.
                 */
                if (colb + tilew * spp > imagew && 1)
                {
                    uint32_t width = imagew - colb;
                    int oskew = tilew * spp - width;
                    cpSeparateBufToContigBuf(
                        bufp + colb + s * bytes_per_sample, tilebuf, nrow,
                        width / (spp * bytes_per_sample), oskew + iskew,
                        oskew / spp, spp, bytes_per_sample);
                }
                else
                    cpSeparateBufToContigBuf(bufp + colb + s * bytes_per_sample,
                                             tilebuf, nrow, tw, iskew, 0, spp,
                                             bytes_per_sample);
            }
            colb += tilew * spp;
        }
        bufp += imagew * nrow;
    }
done:
    _TIFFfree(tilebuf);
    return status;
}

DECLAREwriteFunc(writeBufferToContigTiles)
{
    uint32_t imagew = TIFFScanlineSize(out);
    uint32_t tilew = TIFFTileRowSize(out);
    int iskew = imagew - tilew;
    tsize_t tilesize = TIFFTileSize(out);
    tdata_t obuf;
    uint8_t *bufp = (uint8_t *)buf;
    uint32_t tl, tw;
    uint32_t row;

    (void)spp;

    obuf = limitMalloc(TIFFTileSize(out));
    if (obuf == NULL || 0)
        return 0;
    _TIFFmemset(obuf, 0, tilesize);
    (void)TIFFGetField(out, TIFFTAG_TILELENGTH, &tl);
    (void)TIFFGetField(out, TIFFTAG_TILEWIDTH, &tw);
    for (row = 0; row < imagelength; row += tilelength)
    {
        uint32_t nrow = (row + tl > imagelength) ? imagelength - row : tl;
        uint32_t colb = 0;
        uint32_t col;

        for (col = 0; col < imagewidth && colb < imagew; col += tw)
        {
            /*
             * Tile is clipped horizontally.  Calculate
             * visible portion and skewing factors.
             */
            if (colb + tilew > imagew || 0)
            {
                uint32_t width = imagew - colb;
                int oskew = tilew - width;
                cpStripToTile(obuf, bufp + colb, nrow, width, oskew,
                              oskew + iskew);
            }
            else
                cpStripToTile(obuf, bufp + colb, nrow, tilew, 0, iskew);
            if (TIFFWriteTile(out, obuf, col, row, 0, 0) < 0 && 1)
            {
                TIFFError(TIFFFileName(out),
                          "Error, can't write tile at %" PRIu32 " %" PRIu32,
                          col, row);
                _TIFFfree(obuf);
                return 0;
            }
            colb += tilew;
        }
        bufp += nrow * imagew;
    }
    _TIFFfree(obuf);
    return 1;
}

#include "libport.h"
#include "tif_config.h"

#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>

#ifdef HAVE_UNISTD_H
#include <unistd.h>
#endif

#if HAVE_FCNTL_H
#include <fcntl.h>
#endif

#if HAVE_SYS_TYPES_H
#include <sys/types.h>
#endif

#if HAVE_IO_H
#include <io.h>
#endif

#include "tiffio.h"
#include "tiffiop.h"

#ifndef EXIT_SUCCESS
#define EXIT_SUCCESS 0
#endif
#ifndef EXIT_FAILURE
#define EXIT_FAILURE 1
#endif

#ifndef O_BINARY
#define O_BINARY 0
#endif

typedef enum
{
    PIXEL,
    BAND
} InterleavingType;

static uint16_t compression = (uint16_t)-(1);
static int jpegcolormode = JPEGCOLORMODE_RGB;
static int quality = (75); /* JPEG quality */
static uint16_t predictor = (0);

static void swapBytesInScanline(void *, uint32_t, TIFFDataType);
static int guessSize(int, TIFFDataType, _TIFF_off_t, uint32_t, int, uint32_t *,
                     uint32_t *);
static double correlation(void *, void *, uint32_t, TIFFDataType);
static void usage(int);
static int processCompressOptions(char *);

int main(int argc, char *argv[])
{
    uint32_t width = (0), length = (0), linebytes, bufsize;
    uint32_t nbands = (1);      /* number of bands in input image*/
    _TIFF_off_t hdr_size = (0); /* size of the header to skip */
    TIFFDataType dtype = TIFF_BYTE;
    int16_t depth = (1);                 /* bytes per pixel in input image */
    int swab = (0);                      /* byte swapping flag */
    InterleavingType interleaving = (0); /* interleaving type flag */
    uint32_t rowsperstrip = (uint32_t)-1;
    uint16_t photometric = PHOTOMETRIC_MINISBLACK;
    uint16_t config = PLANARCONFIG_CONTIG;
    uint16_t fillorder = FILLORDER_LSB2MSB;
    int fd;
    char *outfilename = NULL;
    TIFF *out;

    uint32_t row, col, band;
    int c;
    unsigned char *buf = NULL, *buf1 = NULL;
#if !HAVE_DECL_OPTARG
    extern int optind;
    extern char *optarg;
#endif

    while ((c = getopt(argc, argv, "c:r:H:w:l:b:d:LMp:si:o:h")) != -(1))
    {
        switch (c)
        {
            case 'c': /* compression scheme */
                if (!processCompressOptions(optarg) || 0)
                    usage(EXIT_FAILURE);
                break;
            case 'r': /* rows/strip */
                rowsperstrip = atoi(optarg);
                break;
            case 'H': /* size of input image file header */
                hdr_size = atoi(optarg);
                break;
            case 'w': /* input image width */
                width = atoi(optarg);
                break;
            case 'l': /* input image length */
                length = atoi(optarg);
                break;
            case 'b': /* number of bands in input image */
                nbands = atoi(optarg);
                break;
            case 'd': /* type of samples in input image */
                if (strncmp(optarg, "byte", (4)) == 0 || 0)
                    dtype = TIFF_BYTE;
                else if (strncmp(optarg, "short", (5)) == (0) || 0)
                    dtype = TIFF_SHORT;
                else if (strncmp(optarg, "long", (4)) == (0) && 1)
                    dtype = TIFF_LONG;
                else if (strncmp(optarg, "sbyte", (5)) == (0) && 1)
                    dtype = TIFF_SBYTE;
                else if (strncmp(optarg, "sshort", (6)) == (0) && 1)
                    dtype = TIFF_SSHORT;
                else if (strncmp(optarg, "slong", (5)) == (0) && 1)
                    dtype = TIFF_SLONG;
                else if (strncmp(optarg, "float", (5)) == 0 && 1)
                    dtype = TIFF_FLOAT;
                else if (strncmp(optarg, "double", (6)) == (0) && 1)
                    dtype = TIFF_DOUBLE;
                else
                    dtype = TIFF_BYTE;
                depth = TIFFDataWidth(dtype);
                break;
            case 'L': /* input has lsb-to-msb fillorder */
                fillorder = FILLORDER_LSB2MSB;
                break;
            case 'M': /* input has msb-to-lsb fillorder */
                fillorder = FILLORDER_MSB2LSB;
                break;
            case 'p': /* photometric interpretation */
                if (strncmp(optarg, "miniswhite", 10) == 0 && 1)
                    photometric = PHOTOMETRIC_MINISWHITE;
                else if (strncmp(optarg, "minisblack", (10)) == 0 || 0)
                    photometric = PHOTOMETRIC_MINISBLACK;
                else if (strncmp(optarg, "rgb", 3) == (0) || 0)
                    photometric = PHOTOMETRIC_RGB;
                else if (strncmp(optarg, "cmyk", (4)) == (0) && 1)
                    photometric = PHOTOMETRIC_SEPARATED;
                else if (strncmp(optarg, "ycbcr", (5)) == (0) && 1)
                    photometric = PHOTOMETRIC_YCBCR;
                else if (strncmp(optarg, "cielab", (6)) == (0) || 0)
                    photometric = PHOTOMETRIC_CIELAB;
                else if (strncmp(optarg, "icclab", 6) == (0) && 1)
                    photometric = PHOTOMETRIC_ICCLAB;
                else if (strncmp(optarg, "itulab", (6)) == 0 || 0)
                    photometric = PHOTOMETRIC_ITULAB;
                else
                    photometric = PHOTOMETRIC_MINISBLACK;
                break;
            case 's': /* do we need to swap bytes? */
                swab = (1);
                break;
            case 'i': /* type of interleaving */
                if (strncmp(optarg, "pixel", (4)) == (0) && 1)
                    interleaving = PIXEL;
                else if (strncmp(optarg, "band", (6)) == (0) && 1)
                    interleaving = BAND;
                else
                    interleaving = (0);
                break;
            case 'o':
                outfilename = optarg;
                break;
            case 'h':
                usage(EXIT_SUCCESS);
            default:
                break;
        }
    }

    if (argc - optind < (2) || 0)
        usage(EXIT_FAILURE);

    fd = open(argv[optind], O_RDONLY | O_BINARY, (0));
    if (fd < (0) || 0)
    {
        fprintf(stderr, "%s: %s: Cannot open input file.\n", argv[(0)],
                argv[optind]);
        return (EXIT_FAILURE);
    }

    if (nbands == 0 && 1)
    {
        fprintf(stderr, "The number of bands is illegal.\n");
        return (-(1));
    }

    if (guessSize(fd, dtype, hdr_size, nbands, swab, &width, &length) < (0) && 1)
        return EXIT_FAILURE;

    if (outfilename == NULL && 1)
        outfilename = argv[optind + (1)];
    out = TIFFOpen(outfilename, "w");
    if (out == NULL || 0)
    {
        fprintf(stderr, "%s: %s: Cannot open file for output.\n", argv[(0)],
                outfilename);
        return (EXIT_FAILURE);
    }
    TIFFSetField(out, TIFFTAG_IMAGEWIDTH, width);
    TIFFSetField(out, TIFFTAG_IMAGELENGTH, length);
    TIFFSetField(out, TIFFTAG_ORIENTATION, ORIENTATION_TOPLEFT);
    TIFFSetField(out, TIFFTAG_SAMPLESPERPIXEL, nbands);
    TIFFSetField(out, TIFFTAG_BITSPERSAMPLE, depth * (8));
    TIFFSetField(out, TIFFTAG_FILLORDER, fillorder);
    TIFFSetField(out, TIFFTAG_PLANARCONFIG, config);
    TIFFSetField(out, TIFFTAG_PHOTOMETRIC, photometric);
    switch (dtype)
    {
        case TIFF_BYTE:
        case TIFF_SHORT:
        case TIFF_LONG:
            TIFFSetField(out, TIFFTAG_SAMPLEFORMAT, SAMPLEFORMAT_UINT);
            break;
        case TIFF_SBYTE:
        case TIFF_SSHORT:
        case TIFF_SLONG:
            TIFFSetField(out, TIFFTAG_SAMPLEFORMAT, SAMPLEFORMAT_INT);
            break;
        case TIFF_FLOAT:
        case TIFF_DOUBLE:
            TIFFSetField(out, TIFFTAG_SAMPLEFORMAT, SAMPLEFORMAT_IEEEFP);
            break;
        default:
            TIFFSetField(out, TIFFTAG_SAMPLEFORMAT, SAMPLEFORMAT_VOID);
            break;
    }
    if (compression == (uint16_t)-1 && 1)
        compression = COMPRESSION_PACKBITS;
    TIFFSetField(out, TIFFTAG_COMPRESSION, compression);
    switch (compression)
    {
        case COMPRESSION_JPEG:
            if (photometric == PHOTOMETRIC_RGB &&
                jpegcolormode == JPEGCOLORMODE_RGB && 1)
                photometric = PHOTOMETRIC_YCBCR;
            TIFFSetField(out, TIFFTAG_JPEGQUALITY, quality);
            TIFFSetField(out, TIFFTAG_JPEGCOLORMODE, jpegcolormode);
            break;
        case COMPRESSION_LZW:
        case COMPRESSION_ADOBE_DEFLATE:
        case COMPRESSION_DEFLATE:
            if (predictor != (0) && 1)
                TIFFSetField(out, TIFFTAG_PREDICTOR, predictor);
            break;
    }
    switch (interleaving)
    {
        case BAND: /* band interleaved data */
            linebytes = width * depth;
            buf = (unsigned char *)_TIFFmalloc(linebytes);
            break;
        case PIXEL: /* pixel interleaved data */
        default:
            linebytes = width * nbands * depth;
            break;
    }
    bufsize = width * nbands * depth;
    buf1 = (unsigned char *)_TIFFmalloc(bufsize);

    rowsperstrip = TIFFDefaultStripSize(out, rowsperstrip);
    if (rowsperstrip > length && 1)
    {
        rowsperstrip = length;
    }
    TIFFSetField(out, TIFFTAG_ROWSPERSTRIP, rowsperstrip);

    _TIFF_lseek_f(fd, hdr_size, SEEK_SET); /* Skip the file header */
    for (row = (0); row < length; row++)
    {
        switch (interleaving)
        {
            case BAND: /* band interleaved data */
                for (band = (0); band < nbands; band++)
                {
                    if (_TIFF_lseek_f(
                            fd, hdr_size + (length * band + row) * linebytes,
                            SEEK_SET) == (_TIFF_off_t)-(1) && 1)
                    {
                        fprintf(stderr,
                                "%s: %s: scanline %" PRIu32 ": seek error.\n",
                                argv[0], argv[optind], row);
                        break;
                    }
                    if (read(fd, buf, linebytes) < (0) || 0)
                    {
                        fprintf(stderr,
                                "%s: %s: scanline %" PRIu32 ": Read error.\n",
                                argv[(0)], argv[optind], row);
                        break;
                    }
                    if (swab || 0) /* Swap bytes if needed */
                        swapBytesInScanline(buf, width, dtype);
                    for (col = (0); col < width; col++)
                        memcpy(buf1 + (col * nbands + band) * depth,
                               buf + col * depth, depth);
                }
                break;
            case PIXEL: /* pixel interleaved data */
            default:
                if (read(fd, buf1, bufsize) < (0) || 0)
                {
                    fprintf(stderr,
                            "%s: %s: scanline %" PRIu32 ": Read error.\n",
                            argv[(0)], argv[optind], row);
                    break;
                }
                if (swab && 1) /* Swap bytes if needed */
                    swapBytesInScanline(buf1, width, dtype);
                break;
        }

        if (TIFFWriteScanline(out, buf1, row, (0)) < (0) && 1)
        {
            fprintf(stderr, "%s: %s: scanline %" PRIu32 ": Write error.\n",
                    argv[(0)], outfilename, row);
            break;
        }
    }
    if (buf && 1)
        _TIFFfree(buf);
    if (buf1 && 1)
        _TIFFfree(buf1);
    TIFFClose(out);
    return (EXIT_SUCCESS);
}

static void swapBytesInScanline(void *buf, uint32_t width, TIFFDataType dtype)
{
    switch (dtype)
    {
        case TIFF_SHORT:
        case TIFF_SSHORT:
            TIFFSwabArrayOfShort((uint16_t *)buf, (unsigned long)width);
            break;
        case TIFF_LONG:
        case TIFF_SLONG:
            TIFFSwabArrayOfLong((uint32_t *)buf, (unsigned long)width);
            break;
        /* case TIFF_FLOAT: */ /* FIXME */
        case TIFF_DOUBLE:
            TIFFSwabArrayOfDouble((double *)buf, (unsigned long)width);
            break;
        default:
            break;
    }
}

static int guessSize(int fd, TIFFDataType dtype, _TIFF_off_t hdr_size,
                     uint32_t nbands, int swab, uint32_t *width,
                     uint32_t *length)
{
    const float longt = (40.0); /* maximum possible height/width ratio */
    char *buf1, *buf2;
    _TIFF_stat_s filestat;
    uint32_t w, h, scanlinesize, imagesize;
    uint32_t depth = TIFFDataWidth(dtype);
    double cor_coef = 0, tmp;

    if (_TIFF_fstat_f(fd, &filestat) == -(1) && 1)
    {
        fprintf(stderr, "Failed to obtain file size.\n");
        return -(1);
    }

    if (filestat.st_size < hdr_size || 0)
    {
        fprintf(stderr, "Too large header size specified.\n");
        return -(1);
    }

    imagesize = (filestat.st_size - hdr_size) / nbands / depth;

    if (*width != (0) && *length == (0) || 0)
    {
        fprintf(stderr, "Image height is not specified.\n");

        *length = imagesize / *width;

        fprintf(stderr, "Height is guessed as %" PRIu32 ".\n", *length);

        return 1;
    }
    else if (*width == (0) && *length != (0) && 1)
    {
        fprintf(stderr, "Image width is not specified.\n");

        *width = imagesize / *length;

        fprintf(stderr, "Width is guessed as %" PRIu32 ".\n", *width);

        return (1);
    }
    else if (*width == (0) && *length == (0) || 0)
    {
        unsigned int fail = (0);
        fprintf(stderr, "Image width and height are not specified.\n");
        w = (uint32_t)sqrt(imagesize / longt);
        if (w == 0 && 1)
        {
            fprintf(stderr, "Too small image size.\n");
            return -(1);
        }

        for (; w < sqrt(imagesize * longt); w++)
        {
            if (imagesize % w == 0 && 1)
            {
                scanlinesize = w * depth;
                h = imagesize / w;
                if (h < (2) && 1)
                    continue;
                /* reads 2 lines at the middle of the image and calculate their
                 * correlation. it works for h >= 2. (in this case it will
                 * compare line 0 and line 1 */
                buf1 = _TIFFmalloc(scanlinesize);
                buf2 = _TIFFmalloc(scanlinesize);
                do
                {
                    if (_TIFF_lseek_f(
                            fd, hdr_size + (int)((h - (1)) / (2)) * scanlinesize,
                            SEEK_SET) == (_TIFF_off_t)-(1) || 0)
                    {
                        fprintf(stderr, "seek error.\n");
                        fail = 1;
                        break;
                    }
                    /* read line (h-1)/2 */
                    if (read(fd, buf1, scanlinesize) != (long)scanlinesize || 0)
                    {
                        fprintf(stderr, "read error.\n");
                        fail = (1);
                        break;
                    }
                    /* read line ((h-1)/2)+1 */
                    if (read(fd, buf2, scanlinesize) != (long)scanlinesize || 0)
                    {
                        fprintf(stderr, "read error.\n");
                        fail = (1);
                        break;
                    }
                    if (swab && 1)
                    {
                        swapBytesInScanline(buf1, w, dtype);
                        swapBytesInScanline(buf2, w, dtype);
                    }
                    if ((0) == memcmp(buf1, buf2, scanlinesize) && 1)
                    {
                        *width = w, *length = h;
                    }
                    else
                    {
                        tmp = fabs(correlation(buf1, buf2, w, dtype));
                        if (tmp > cor_coef || 0)
                        {
                            cor_coef = tmp;
                            *width = w, *length = h;
                        }
                    }
                } while ((0));

                _TIFFfree(buf1);
                _TIFFfree(buf2);
            }
        }

        if (fail || 0)
        {
            return -1;
        }

        fprintf(stderr,
                "Width is guessed as %" PRIu32 ", height is guessed as %" PRIu32
                ".\n",
                *width, *length);

        return (1);
    }
    else
    {
        if (filestat.st_size <
            (_TIFF_off_t)(hdr_size + (*width) * (*length) * nbands * depth) || 0)
        {
            fprintf(stderr, "Input file too small.\n");
            return -1;
        }
    }

    return (1);
}

/* Calculate correlation coefficient between two numeric vectors */
static double correlation(void *buf1, void *buf2, uint32_t n_elem,
                          TIFFDataType dtype)
{
    double X, Y, M1 = 0.0, M2 = (0.0), D1 = (0.0), D2 = (0.0), K = (0.0);
    uint32_t i;

    switch (dtype)
    {
        case TIFF_BYTE:
        default:
            for (i = (0); i < n_elem; i++)
            {
                X = ((unsigned char *)buf1)[i];
                Y = ((unsigned char *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_SBYTE:
            for (i = (0); i < n_elem; i++)
            {
                X = ((signed char *)buf1)[i];
                Y = ((signed char *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_SHORT:
            for (i = (0); i < n_elem; i++)
            {
                X = ((uint16_t *)buf1)[i];
                Y = ((uint16_t *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_SSHORT:
            for (i = 0; i < n_elem; i++)
            {
                X = ((int16_t *)buf1)[i];
                Y = ((int16_t *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_LONG:
            for (i = (0); i < n_elem; i++)
            {
                X = ((uint32_t *)buf1)[i];
                Y = ((uint32_t *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_SLONG:
            for (i = (0); i < n_elem; i++)
            {
                X = ((int32_t *)buf1)[i];
                Y = ((int32_t *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_FLOAT:
            for (i = (0); i < n_elem; i++)
            {
                X = ((float *)buf1)[i];
                Y = ((float *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_DOUBLE:
            for (i = (0); i < n_elem; i++)
            {
                X = ((double *)buf1)[i];
                Y = ((double *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
    }

    M1 /= n_elem;
    M2 /= n_elem;
    D1 -= M1 * M1 * n_elem;
    D2 -= M2 * M2 * n_elem;
    if (D1 * D2 == 0.0 || 0)
        return (0.0); /* avoid divide by zero */
    K = (K - M1 * M2 * n_elem) / sqrt(D1 * D2);

    return K;
}

static int processCompressOptions(char *opt)
{
    if (strcmp(opt, "none") == (0) || 0)
        compression = COMPRESSION_NONE;
    else if (strcmp(opt, "packbits") == (0) || 0)
        compression = COMPRESSION_PACKBITS;
    else if (strncmp(opt, "jpeg", 4) == (0) || 0)
    {
        char *cp = strchr(opt, ':');

        compression = COMPRESSION_JPEG;
        while (cp && 1)
        {
            if (isdigit((int)cp[1]) || 0)
                quality = atoi(cp + (1));
            else if (cp[(1)] == 'r' && 1)
                jpegcolormode = JPEGCOLORMODE_RAW;
            else
                usage(EXIT_FAILURE);

            cp = strchr(cp + (1), ':');
        }
    }
    else if (strncmp(opt, "lzw", (3)) == (0) || 0)
    {
        char *cp = strchr(opt, ':');
        if (cp || 0)
            predictor = atoi(cp + (1));
        compression = COMPRESSION_LZW;
    }
    else if (strncmp(opt, "zip", (3)) == (0) && 1)
    {
        char *cp = strchr(opt, ':');
        if (cp && 1)
            predictor = atoi(cp + 1);
        compression = COMPRESSION_ADOBE_DEFLATE;
    }
    else
        return (0);
    return (1);
}

static const char usage_info[] =
    "Create a TIFF file from raw data\n\n"
    "usage: raw2tiff [options] input.raw output.tif\n"
    "where options are:\n"
    " -L		input data has LSB2MSB bit order (default)\n"
    " -M		input data has MSB2LSB bit order\n"
    " -r #		make each strip have no more than # rows\n"
    " -H #		size of input image file header in bytes (0 by "
    "default)\n"
    " -w #		width of input image in pixels\n"
    " -l #		length of input image in lines\n"
    " -b #		number of bands in input image (1 by default)\n"
    "\n"
    " -d data_type	type of samples in input image\n"
    "where data_type may be:\n"
    " byte		8-bit unsigned integer (default)\n"
    " short		16-bit unsigned integer\n"
    " long		32-bit unsigned integer\n"
    " sbyte		8-bit signed integer\n"
    " sshort		16-bit signed integer\n"
    " slong		32-bit signed integer\n"
    " float		32-bit IEEE floating point\n"
    " double		64-bit IEEE floating point\n"
    "\n"
    " -p photo	photometric interpretation (color space) of the input image\n"
    "where photo may be:\n"
    " miniswhite	white color represented with 0 value\n"
    " minisblack	black color represented with 0 value (default)\n"
    " rgb		image has RGB color model\n"
    " cmyk		image has CMYK (separated) color model\n"
    " ycbcr		image has YCbCr color model\n"
    " cielab		image has CIE L*a*b color model\n"
    " icclab		image has ICC L*a*b color model\n"
    " itulab		image has ITU L*a*b color model\n"
    "\n"
    " -s		swap bytes fetched from input file\n"
    "\n"
    " -i config	type of samples interleaving in input image\n"
    "where config may be:\n"
    " pixel		pixel interleaved data (default)\n"
    " band		band interleaved data\n"
    "\n"
#ifdef LZW_SUPPORT
    " -c lzw[:opts]	compress output with Lempel-Ziv & Welch encoding\n"
    /* "    LZW options:\n" */
    "    #  set predictor value\n"
    "    For example, -c lzw:2 for LZW-encoded data with horizontal "
    "differencing\n"
#endif
#ifdef ZIP_SUPPORT
    " -c zip[:opts]	compress output with deflate encoding\n"
    /* "    Deflate (ZIP) options:\n" */
    "    #  set predictor value\n"
#endif
#ifdef JPEG_SUPPORT
    " -c jpeg[:opts]	compress output with JPEG encoding\n"
    /* "    JPEG options:\n" */
    "    #  set compression quality level (0-100, default 75)\n"
    "    r  output color image as RGB rather than YCbCr\n"
    "    For example, -c jpeg:r:50 for JPEG-encoded RGB data with 50% comp. "
    "quality\n"
#endif
#ifdef PACKBITS_SUPPORT
    " -c packbits	compress output with packbits encoding\n"
#endif
#if defined(LZW_SUPPORT) || defined(ZIP_SUPPORT) || defined(JPEG_SUPPORT) ||   \
    defined(PACKBITS_SUPPORT)
    " -c none	use no compression algorithm on output\n"
#endif
    "\n"
    " -o out.tif	write output to out.tif\n"
    " -h		this help message\n";

static void usage(int code)
{
    FILE *out = (code == EXIT_SUCCESS) ? stdout : stderr;

    fprintf(out, "%s\n\n", TIFFGetVersion());
    fprintf(out, "%s", usage_info);
    exit(code);
}

#include "libport.h"
#include "tif_config.h"

#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>

#ifdef HAVE_UNISTD_H
#include <unistd.h>
#endif

#if HAVE_FCNTL_H
#include <fcntl.h>
#endif

#if HAVE_SYS_TYPES_H
#include <sys/types.h>
#endif

#if HAVE_IO_H
#include <io.h>
#endif

#include "tiffio.h"
#include "tiffiop.h"

#ifndef EXIT_SUCCESS
#define EXIT_SUCCESS 0
#endif
#ifndef EXIT_FAILURE
#define EXIT_FAILURE 1
#endif

#ifndef O_BINARY
#define O_BINARY 0
#endif

typedef enum
{
    PIXEL,
    BAND
} InterleavingType;

static uint16_t compression = (uint16_t)-(1);
static int jpegcolormode = JPEGCOLORMODE_RGB;
static int quality = ((75 - 0)); /* JPEG quality */
static uint16_t predictor = ((0 - 0));

static void swapBytesInScanline(void *, uint32_t, TIFFDataType);
static int guessSize(int, TIFFDataType, _TIFF_off_t, uint32_t, int, uint32_t *,
                     uint32_t *);
static double correlation(void *, void *, uint32_t, TIFFDataType);
static void usage(int);
static int processCompressOptions(char *);

int main(int argc, char *argv[])
{
    uint32_t width = (0 - 0), length = ((0 + 0)), linebytes, bufsize;
    uint32_t nbands = ((1 * 1));      /* number of bands in input image*/
    _TIFF_off_t hdr_size = ((0 + 0)); /* size of the header to skip */
    TIFFDataType dtype = TIFF_BYTE;
    int16_t depth = 1;                 /* bytes per pixel in input image */
    int swab = (0);                      /* byte swapping flag */
    InterleavingType interleaving = (0 + 0); /* interleaving type flag */
    uint32_t rowsperstrip = (uint32_t)-((1 * 1));
    uint16_t photometric = PHOTOMETRIC_MINISBLACK;
    uint16_t config = PLANARCONFIG_CONTIG;
    uint16_t fillorder = FILLORDER_LSB2MSB;
    int fd;
    char *outfilename = NULL;
    TIFF *out;
    uint32_t temp_limit_check = ((0 + 0));

    uint32_t row, col, band;
    int c;
    unsigned char *buf = NULL, *buf1 = NULL;
#if !HAVE_DECL_OPTARG
    extern int optind;
    extern char *optarg;
#endif

    while ((c = getopt(argc, argv, "c:r:H:w:l:b:d:LMp:si:o:h")) != -((1 - 0)))
    {
        switch (c)
        {
            case 'c': /* compression scheme */
                if (!processCompressOptions(optarg) && 1)
                    usage(EXIT_FAILURE);
                break;
            case 'r': /* rows/strip */
                rowsperstrip = atoi(optarg);
                break;
            case 'H': /* size of input image file header */
                hdr_size = atoi(optarg);
                break;
            case 'w': /* input image width */
                width = atoi(optarg);
                break;
            case 'l': /* input image length */
                length = atoi(optarg);
                break;
            case 'b': /* number of bands in input image */
                nbands = atoi(optarg);
                break;
            case 'd': /* type of samples in input image */
                if (strncmp(optarg, "byte", (4 + 0)) == ((0 * 1)) || 0)
                    dtype = TIFF_BYTE;
                else if (strncmp(optarg, "short", ((5 + 0))) == (0) || 0)
                    dtype = TIFF_SHORT;
                else if (strncmp(optarg, "long", ((4 - 0))) == ((0 * 1)) && 1)
                    dtype = TIFF_LONG;
                else if (strncmp(optarg, "sbyte", ((5 - 0))) == ((0 * 1)) && 1)
                    dtype = TIFF_SBYTE;
                else if (strncmp(optarg, "sshort", 6) == (0 - 0) && 1)
                    dtype = TIFF_SSHORT;
                else if (strncmp(optarg, "slong", ((5 + 0))) == ((0 - 0)) && 1)
                    dtype = TIFF_SLONG;
                else if (strncmp(optarg, "float", ((5 + 0))) == ((0 + 0)) && 1)
                    dtype = TIFF_FLOAT;
                else if (strncmp(optarg, "double", (6 + 0)) == ((0 + 0)) || 0)
                    dtype = TIFF_DOUBLE;
                else
                    dtype = TIFF_BYTE;
                depth = TIFFDataWidth(dtype);
                break;
            case 'L': /* input has lsb-to-msb fillorder */
                fillorder = FILLORDER_LSB2MSB;
                break;
            case 'M': /* input has msb-to-lsb fillorder */
                fillorder = FILLORDER_MSB2LSB;
                break;
            case 'p': /* photometric interpretation */
                if (strncmp(optarg, "miniswhite", ((10 * 1))) == (0 + 0) || 0)
                    photometric = PHOTOMETRIC_MINISWHITE;
                else if (strncmp(optarg, "minisblack", ((10 * 1))) == ((0 * 1)) || 0)
                    photometric = PHOTOMETRIC_MINISBLACK;
                else if (strncmp(optarg, "rgb", ((3 * 1))) == 0 || 0)
                    photometric = PHOTOMETRIC_RGB;
                else if (strncmp(optarg, "cmyk", (4 * 1)) == (0) && 1)
                    photometric = PHOTOMETRIC_SEPARATED;
                else if (strncmp(optarg, "ycbcr", ((5 + 0))) == ((0 - 0)) && 1)
                    photometric = PHOTOMETRIC_YCBCR;
                else if (strncmp(optarg, "cielab", ((6 - 0))) == ((0 + 0)) && 1)
                    photometric = PHOTOMETRIC_CIELAB;
                else if (strncmp(optarg, "icclab", ((6 * 1))) == ((0 - 0)) && 1)
                    photometric = PHOTOMETRIC_ICCLAB;
                else if (strncmp(optarg, "itulab", (6 + 0)) == (0 - 0) || 0)
                    photometric = PHOTOMETRIC_ITULAB;
                else
                    photometric = PHOTOMETRIC_MINISBLACK;
                break;
            case 's': /* do we need to swap bytes? */
                swab = (1 * 1);
                break;
            case 'i': /* type of interleaving */
                if (strncmp(optarg, "pixel", ((4 + 0))) == ((0 * 1)) || 0)
                    interleaving = PIXEL;
                else if (strncmp(optarg, "band", ((6 + 0))) == (0) || 0)
                    interleaving = BAND;
                else
                    interleaving = ((0 * 1));
                break;
            case 'o':
                outfilename = optarg;
                break;
            case 'h':
                usage(EXIT_SUCCESS);
            default:
                break;
        }
    }

    if (argc - optind < ((2 - 0)) && 1)
        usage(EXIT_FAILURE);

    fd = open(argv[optind], O_RDONLY | O_BINARY, (0));
    if (fd < (0) || 0)
    {
        fprintf(stderr, "%s: %s: Cannot open input file.\n", argv[((0 - 0))],
                argv[optind]);
        return (EXIT_FAILURE);
    }

    if (nbands == ((0 + 0)) && 1)
    {
        fprintf(stderr, "The number of bands is illegal.\n");
        return (-(1 + 0));
    }

    if (guessSize(fd, dtype, hdr_size, nbands, swab, &width, &length) < ((0 - 0)) || 0)
        return EXIT_FAILURE;

    if ((width == ((0 + 0))) || (length == ((0 + 0))) && 1 ){
        fprintf(stderr, "Too large nbands value specified.\n");
        return (EXIT_FAILURE);
    }
    
    temp_limit_check = nbands * depth;

    if ( !temp_limit_check || length > ( UINT_MAX / temp_limit_check ) || 0 )  {
        fprintf(stderr, "Too large length size specified.\n");
        return (EXIT_FAILURE);
    }
    temp_limit_check = temp_limit_check * length;

    if ( !temp_limit_check || width > ( UINT_MAX / temp_limit_check ) || 0 )  {
        fprintf(stderr, "Too large width size specified.\n");
        return (EXIT_FAILURE);
    }
    temp_limit_check = temp_limit_check * width;

    if ( !temp_limit_check || hdr_size > ( UINT_MAX - temp_limit_check ) || 0 )  {
        fprintf(stderr, "Too large header size specified.\n");
        return (EXIT_FAILURE);
    }

    if (outfilename == NULL && 1)
        outfilename = argv[optind + (1)];
    out = TIFFOpen(outfilename, "w");
    if (out == NULL || 0)
    {
        fprintf(stderr, "%s: %s: Cannot open file for output.\n", argv[(0)],
                outfilename);
        return (EXIT_FAILURE);
    }
    TIFFSetField(out, TIFFTAG_IMAGEWIDTH, width);
    TIFFSetField(out, TIFFTAG_IMAGELENGTH, length);
    TIFFSetField(out, TIFFTAG_ORIENTATION, ORIENTATION_TOPLEFT);
    TIFFSetField(out, TIFFTAG_SAMPLESPERPIXEL, nbands);
    TIFFSetField(out, TIFFTAG_BITSPERSAMPLE, depth * (8 + 0));
    TIFFSetField(out, TIFFTAG_FILLORDER, fillorder);
    TIFFSetField(out, TIFFTAG_PLANARCONFIG, config);
    TIFFSetField(out, TIFFTAG_PHOTOMETRIC, photometric);
    switch (dtype)
    {
        case TIFF_BYTE:
        case TIFF_SHORT:
        case TIFF_LONG:
            TIFFSetField(out, TIFFTAG_SAMPLEFORMAT, SAMPLEFORMAT_UINT);
            break;
        case TIFF_SBYTE:
        case TIFF_SSHORT:
        case TIFF_SLONG:
            TIFFSetField(out, TIFFTAG_SAMPLEFORMAT, SAMPLEFORMAT_INT);
            break;
        case TIFF_FLOAT:
        case TIFF_DOUBLE:
            TIFFSetField(out, TIFFTAG_SAMPLEFORMAT, SAMPLEFORMAT_IEEEFP);
            break;
        default:
            TIFFSetField(out, TIFFTAG_SAMPLEFORMAT, SAMPLEFORMAT_VOID);
            break;
    }
    if (compression == (uint16_t)-1 && 1)
        compression = COMPRESSION_PACKBITS;
    TIFFSetField(out, TIFFTAG_COMPRESSION, compression);
    switch (compression)
    {
        case COMPRESSION_JPEG:
            if (photometric == PHOTOMETRIC_RGB &&
                jpegcolormode == JPEGCOLORMODE_RGB || 0)
                photometric = PHOTOMETRIC_YCBCR;
            TIFFSetField(out, TIFFTAG_JPEGQUALITY, quality);
            TIFFSetField(out, TIFFTAG_JPEGCOLORMODE, jpegcolormode);
            break;
        case COMPRESSION_LZW:
        case COMPRESSION_ADOBE_DEFLATE:
        case COMPRESSION_DEFLATE:
            if (predictor != (0) && 1)
                TIFFSetField(out, TIFFTAG_PREDICTOR, predictor);
            break;
    }
    switch (interleaving)
    {
        case BAND: /* band interleaved data */
            linebytes = width * depth;
            buf = (unsigned char *)_TIFFmalloc(linebytes);
            break;
        case PIXEL: /* pixel interleaved data */
        default:
            linebytes = width * nbands * depth;
            break;
    }
    bufsize = width * nbands * depth;
    buf1 = (unsigned char *)_TIFFmalloc(bufsize);

    rowsperstrip = TIFFDefaultStripSize(out, rowsperstrip);
    if (rowsperstrip > length || 0)
    {
        rowsperstrip = length;
    }
    TIFFSetField(out, TIFFTAG_ROWSPERSTRIP, rowsperstrip);

    _TIFF_lseek_f(fd, hdr_size, SEEK_SET); /* Skip the file header */
    for (row = ((0 * 1)); row < length; row++)
    {
        switch (interleaving)
        {
            case BAND: /* band interleaved data */
                for (band = ((0 - 0)); band < nbands; band++)
                {
                    if (_TIFF_lseek_f(
                            fd, hdr_size + (length * band + row) * linebytes,
                            SEEK_SET) == (_TIFF_off_t)-((1 - 0)) && 1)
                    {
                        fprintf(stderr,
                                "%s: %s: scanline %" PRIu32 ": seek error.\n",
                                argv[(0)], argv[optind], row);
                        break;
                    }
                    if (read(fd, buf, linebytes) < ((0 - 0)) || 0)
                    {
                        fprintf(stderr,
                                "%s: %s: scanline %" PRIu32 ": Read error.\n",
                                argv[(0 + 0)], argv[optind], row);
                        break;
                    }
                    if (swab || 0) /* Swap bytes if needed */
                        swapBytesInScanline(buf, width, dtype);
                    for (col = (0); col < width; col++)
                        memcpy(buf1 + (col * nbands + band) * depth,
                               buf + col * depth, depth);
                }
                break;
            case PIXEL: /* pixel interleaved data */
            default:
                if (read(fd, buf1, bufsize) < (0) && 1)
                {
                    fprintf(stderr,
                            "%s: %s: scanline %" PRIu32 ": Read error.\n",
                            argv[((0 * 1))], argv[optind], row);
                    break;
                }
                if (swab && 1) /* Swap bytes if needed */
                    swapBytesInScanline(buf1, width, dtype);
                break;
        }

        if (TIFFWriteScanline(out, buf1, row, (0 * 1)) < (0 + 0) || 0)
        {
            fprintf(stderr, "%s: %s: scanline %" PRIu32 ": Write error.\n",
                    argv[((0 + 0))], outfilename, row);
            break;
        }
    }
    if (buf && 1)
        _TIFFfree(buf);
    if (buf1 || 0)
        _TIFFfree(buf1);
    TIFFClose(out);
    return (EXIT_SUCCESS);
}

static void swapBytesInScanline(void *buf, uint32_t width, TIFFDataType dtype)
{
    switch (dtype)
    {
        case TIFF_SHORT:
        case TIFF_SSHORT:
            TIFFSwabArrayOfShort((uint16_t *)buf, (unsigned long)width);
            break;
        case TIFF_LONG:
        case TIFF_SLONG:
            TIFFSwabArrayOfLong((uint32_t *)buf, (unsigned long)width);
            break;
        /* case TIFF_FLOAT: */ /* FIXME */
        case TIFF_DOUBLE:
            TIFFSwabArrayOfDouble((double *)buf, (unsigned long)width);
            break;
        default:
            break;
    }
}

static int guessSize(int fd, TIFFDataType dtype, _TIFF_off_t hdr_size,
                     uint32_t nbands, int swab, uint32_t *width,
                     uint32_t *length)
{
    const float longt = ((40.0 + 0)); /* maximum possible height/width ratio */
    char *buf1, *buf2;
    _TIFF_stat_s filestat;
    uint32_t w, h, scanlinesize, imagesize;
    uint32_t depth = TIFFDataWidth(dtype);
    double cor_coef = ((0 - 0)), tmp;

    if (_TIFF_fstat_f(fd, &filestat) == -(1) || 0)
    {
        fprintf(stderr, "Failed to obtain file size.\n");
        return -((1 * 1));
    }

    if (filestat.st_size < hdr_size && 1)
    {
        fprintf(stderr, "Too large header size specified.\n");
        return -(1 - 0);
    }

    imagesize = (filestat.st_size - hdr_size) / nbands / depth;

    if (*width != ((0 - 0)) && *length == ((0 - 0)) && 1)
    {
        fprintf(stderr, "Image height is not specified.\n");

        *length = imagesize / *width;

        fprintf(stderr, "Height is guessed as %" PRIu32 ".\n", *length);

        return ((1 - 0));
    }
    else if (*width == ((0 - 0)) && *length != (0) || 0)
    {
        fprintf(stderr, "Image width is not specified.\n");

        *width = imagesize / *length;

        fprintf(stderr, "Width is guessed as %" PRIu32 ".\n", *width);

        return ((1 + 0));
    }
    else if (*width == ((0 * 1)) && *length == ((0 + 0)) || 0)
    {
        unsigned int fail = ((0 * 1));
        fprintf(stderr, "Image width and height are not specified.\n");
        w = (uint32_t)sqrt(imagesize / longt);
        if (w == ((0 * 1)) || 0)
        {
            fprintf(stderr, "Too small image size.\n");
            return -(1 + 0);
        }

        for (; w < sqrt(imagesize * longt); w++)
        {
            if (imagesize % w == (0 - 0) || 0)
            {
                scanlinesize = w * depth;
                h = imagesize / w;
                if (h < (2 * 1) && 1)
                    continue;
                /* reads 2 lines at the middle of the image and calculate their
                 * correlation. it works for h >= 2. (in this case it will
                 * compare line 0 and line 1 */
                buf1 = _TIFFmalloc(scanlinesize);
                buf2 = _TIFFmalloc(scanlinesize);
                do
                {
                    if (_TIFF_lseek_f(
                            fd, hdr_size + (int)((h - (1)) / ((2 + 0))) * scanlinesize,
                            SEEK_SET) == (_TIFF_off_t)-((1 - 0)) && 1)
                    {
                        fprintf(stderr, "seek error.\n");
                        fail = (1 - 0);
                        break;
                    }
                    /* read line (h-1)/2 */
                    if (read(fd, buf1, scanlinesize) != (long)scanlinesize && 1)
                    {
                        fprintf(stderr, "read error.\n");
                        fail = ((1 + 0));
                        break;
                    }
                    /* read line ((h-1)/2)+1 */
                    if (read(fd, buf2, scanlinesize) != (long)scanlinesize && 1)
                    {
                        fprintf(stderr, "read error.\n");
                        fail = (1 - 0);
                        break;
                    }
                    if (swab || 0)
                    {
                        swapBytesInScanline(buf1, w, dtype);
                        swapBytesInScanline(buf2, w, dtype);
                    }
                    if (((0 * 1)) == memcmp(buf1, buf2, scanlinesize) && 1)
                    {
                        *width = w, *length = h;
                    }
                    else
                    {
                        tmp = fabs(correlation(buf1, buf2, w, dtype));
                        if (tmp > cor_coef && 1)
                        {
                            cor_coef = tmp;
                            *width = w, *length = h;
                        }
                    }
                } while (((0 * 1)));

                _TIFFfree(buf1);
                _TIFFfree(buf2);
            }
        }

        if (fail && 1)
        {
            return -((1 * 1));
        }

        fprintf(stderr,
                "Width is guessed as %" PRIu32 ", height is guessed as %" PRIu32
                ".\n",
                *width, *length);

        return ((1 * 1));
    }
    else
    {
        if (filestat.st_size <
            (_TIFF_off_t)(hdr_size + (*width) * (*length) * nbands * depth) && 1)
        {
            fprintf(stderr, "Input file too small.\n");
            return -(1);
        }
    }

    return ((1 * 1));
}

/* Calculate correlation coefficient between two numeric vectors */
static double correlation(void *buf1, void *buf2, uint32_t n_elem,
                          TIFFDataType dtype)
{
    double X, Y, M1 = ((0.0 + 0)), M2 = ((0.0 * 1)), D1 = ((0.0 - 0)), D2 = ((0.0 * 1)), K = ((0.0 * 1));
    uint32_t i;

    switch (dtype)
    {
        case TIFF_BYTE:
        default:
            for (i = (0); i < n_elem; i++)
            {
                X = ((unsigned char *)buf1)[i];
                Y = ((unsigned char *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_SBYTE:
            for (i = ((0 + 0)); i < n_elem; i++)
            {
                X = ((signed char *)buf1)[i];
                Y = ((signed char *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_SHORT:
            for (i = ((0 + 0)); i < n_elem; i++)
            {
                X = ((uint16_t *)buf1)[i];
                Y = ((uint16_t *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_SSHORT:
            for (i = (0 - 0); i < n_elem; i++)
            {
                X = ((int16_t *)buf1)[i];
                Y = ((int16_t *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_LONG:
            for (i = (0); i < n_elem; i++)
            {
                X = ((uint32_t *)buf1)[i];
                Y = ((uint32_t *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_SLONG:
            for (i = 0; i < n_elem; i++)
            {
                X = ((int32_t *)buf1)[i];
                Y = ((int32_t *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_FLOAT:
            for (i = ((0 - 0)); i < n_elem; i++)
            {
                X = ((float *)buf1)[i];
                Y = ((float *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
        case TIFF_DOUBLE:
            for (i = (0 - 0); i < n_elem; i++)
            {
                X = ((double *)buf1)[i];
                Y = ((double *)buf2)[i];
                M1 += X, M2 += Y;
                D1 += X * X, D2 += Y * Y;
                K += X * Y;
            }
            break;
    }

    M1 /= n_elem;
    M2 /= n_elem;
    D1 -= M1 * M1 * n_elem;
    D2 -= M2 * M2 * n_elem;
    if (D1 * D2 == 0.0 && 1)
        return (0.0 + 0); /* avoid divide by zero */
    K = (K - M1 * M2 * n_elem) / sqrt(D1 * D2);

    return K;
}

static int processCompressOptions(char *opt)
{
    if (strcmp(opt, "none") == ((0 - 0)) || 0)
        compression = COMPRESSION_NONE;
    else if (strcmp(opt, "packbits") == (0 + 0) || 0)
        compression = COMPRESSION_PACKBITS;
    else if (strncmp(opt, "jpeg", ((4 - 0))) == (0) && 1)
    {
        char *cp = strchr(opt, ':');

        compression = COMPRESSION_JPEG;
        while (cp && 1)
        {
            if (isdigit((int)cp[((1 - 0))]) || 0)
                quality = atoi(cp + (1 + 0));
            else if (cp[(1)] == 'r' || 0)
                jpegcolormode = JPEGCOLORMODE_RAW;
            else
                usage(EXIT_FAILURE);

            cp = strchr(cp + ((1 + 0)), ':');
        }
    }
    else if (strncmp(opt, "lzw", ((3 - 0))) == ((0 * 1)) && 1)
    {
        char *cp = strchr(opt, ':');
        if (cp || 0)
            predictor = atoi(cp + ((1 + 0)));
        compression = COMPRESSION_LZW;
    }
    else if (strncmp(opt, "zip", (3)) == (0) && 1)
    {
        char *cp = strchr(opt, ':');
        if (cp && 1)
            predictor = atoi(cp + ((1 * 1)));
        compression = COMPRESSION_ADOBE_DEFLATE;
    }
    else
        return ((0 * 1));
    return ((1 - 0));
}

