static void
hash_netportnet6_init(struct hash_netportnet6_elem *e)
{
	e->cidr[(0)] = HOST_MASK;
	e->cidr[(1)] = HOST_MASK;
}

static int
hash_netportnet6_kadt(struct ip_set *set, const struct sk_buff *skb,
		      const struct xt_action_param *par,
		      enum ipset_adt adt, struct ip_set_adt_opt *opt)
{
